"use client";

import { motion, useReducedMotion } from "framer-motion";

export function PrimaryButton({ children }: { children: React.ReactNode }) {
  const shouldReduceMotion = useReducedMotion();

  return (
    <motion.button
      whileTap={shouldReduceMotion ? undefined : { scale: 0.98 }}
      transition={{ duration: 0.12, ease: [0.22, 1, 0.36, 1] }}
      className="inline-flex h-10 items-center justify-center rounded-md bg-emerald-700 px-4 text-sm font-medium text-white transition-colors duration-150 hover:bg-emerald-800 focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-emerald-600 active:bg-emerald-900 disabled:pointer-events-none disabled:opacity-50 dark:focus-visible:outline-emerald-400"
    >
      {children}
    </motion.button>
  );
}

export function GhostButton({ children }: { children: React.ReactNode }) {
  return (
    <button className="inline-flex h-10 items-center justify-center rounded-md border border-stone-300 px-4 text-sm font-medium text-stone-700 transition-colors duration-150 hover:border-amber-700 hover:bg-amber-700 hover:text-white focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-emerald-600 active:scale-[0.98] active:bg-amber-800 disabled:pointer-events-none disabled:opacity-50 dark:border-stone-700 dark:text-stone-200 dark:hover:border-amber-700 dark:focus-visible:outline-emerald-400">
      {children}
    </button>
  );
}

"use client";

import { useState } from "react";
import { motion, useReducedMotion } from "framer-motion";

export function ToggleSwitch({ label }: { label: string }) {
  const [checked, setChecked] = useState(false);
  const shouldReduceMotion = useReducedMotion();

  return (
    <label className="flex items-center gap-3 cursor-pointer select-none">
      <motion.button
        role="switch"
        aria-checked={checked}
        onClick={() => setChecked((v) => !v)}
        className={`relative h-6 w-11 shrink-0 rounded-full transition-colors duration-150 focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-emerald-600 dark:focus-visible:outline-emerald-400 ${
          checked ? "bg-emerald-700" : "bg-stone-300 dark:bg-stone-700"
        }`}
      >
        <motion.span
          animate={{ x: checked ? 22 : 2 }}
          transition={
            shouldReduceMotion
              ? { duration: 0 }
              : { type: "spring", stiffness: 700, damping: 32 }
          }
          className="absolute top-0.5 block h-5 w-5 rounded-full bg-white shadow-sm"
        />
      </motion.button>
      <span className="text-sm text-stone-700 dark:text-stone-200">{label}</span>
    </label>
  );
}

export function TextField({ label }: { label: string }) {
  return (
    <div className="relative w-full">
      <input
        id="text-field"
        type="text"
        placeholder=" "
        className="peer w-full rounded-md border border-stone-300 bg-stone-100 px-3 pb-2 pt-5 text-sm text-stone-900 outline-none transition-[border-color,box-shadow] duration-150 focus:border-emerald-600 focus:ring-2 focus:ring-emerald-600/25 dark:border-stone-700 dark:bg-stone-950 dark:text-stone-100 dark:focus:border-emerald-400 dark:focus:ring-emerald-400/25"
      />
      <label
        htmlFor="text-field"
        className="pointer-events-none absolute left-3 top-1/2 -translate-y-1/2 text-sm text-stone-500 transition-[top,font-size,color] duration-150 ease-out peer-focus:top-3.5 peer-focus:text-[11px] peer-focus:text-emerald-700 peer-[:not(:placeholder-shown)]:top-3.5 peer-[:not(:placeholder-shown)]:text-[11px] dark:peer-focus:text-emerald-400"
      >
        {label}
      </label>
    </div>
  );
}

"use client";

import { useEffect, useId, useRef, useState, type ReactNode } from "react";
import { AnimatePresence, motion, useReducedMotion } from "framer-motion";

const cx = (...c: Array<string | false | null | undefined>) => c.filter(Boolean).join(" ");

export interface SelectProps {
  options: string[];
  /** The accessible name of the control, e.g. "Department". */
  label: string;
  /** Index of the selected option. Controlled when given with `onChange`. */
  value?: number;
  defaultValue?: number;
  onChange?: (index: number) => void;
  /** A glyph before the selected label, e.g. a calendar for a date range. */
  icon?: ReactNode;
  /** `sm` is the toolbar height, for a card head; `md` is the form height. */
  size?: "sm" | "md";
  /** Which edge of the trigger the list hangs from when it is narrower than the list. */
  align?: "start" | "end";
  className?: string;
}

const SIZE = {
  sm: "h-8 gap-2 px-3 text-xs",
  md: "h-10 gap-2 px-3.5 text-sm",
};

/**
 * A listbox behind a combobox trigger, with the house sliding highlight
 * between options. Ids come from `useId` so several selects can share a page,
 * and the highlight's `layoutId` is scoped the same way so two open lists do
 * not trade one highlight between them.
 */
export function Select({
  options,
  label,
  value,
  defaultValue = 0,
  onChange,
  icon,
  size = "md",
  align = "start",
  className = "",
}: SelectProps) {
  const uid = useId();
  const [open, setOpen] = useState(false);
  const [inner, setInner] = useState(defaultValue);
  const selected = value ?? inner;
  const [highlighted, setHighlighted] = useState(selected);
  const rootRef = useRef<HTMLDivElement>(null);
  const shouldReduceMotion = useReducedMotion();

  const choose = (i: number) => {
    if (value === undefined) setInner(i);
    onChange?.(i);
    setOpen(false);
  };

  useEffect(() => {
    if (!open) return;
    const onClick = (e: MouseEvent) => {
      if (rootRef.current && !rootRef.current.contains(e.target as Node)) setOpen(false);
    };
    document.addEventListener("mousedown", onClick);
    return () => document.removeEventListener("mousedown", onClick);
  }, [open]);

  const handleKeyDown = (e: React.KeyboardEvent) => {
    if (e.key === "ArrowDown") {
      e.preventDefault();
      if (!open) return setOpen(true);
      setHighlighted((h) => Math.min(h + 1, options.length - 1));
    } else if (e.key === "ArrowUp") {
      e.preventDefault();
      setHighlighted((h) => Math.max(h - 1, 0));
    } else if (e.key === "Enter" || e.key === " ") {
      e.preventDefault();
      if (open) choose(highlighted);
      else setOpen(true);
    } else if (e.key === "Escape") {
      setOpen(false);
    }
  };

  return (
    <div ref={rootRef} className={cx("relative", size === "md" ? "w-full max-w-xs" : "inline-block", className)}>
      <button
        type="button"
        role="combobox"
        aria-label={label}
        aria-expanded={open}
        aria-haspopup="listbox"
        aria-controls={`${uid}-listbox`}
        onClick={() => {
          setOpen((v) => !v);
          setHighlighted(selected);
        }}
        onKeyDown={handleKeyDown}
        className={cx(
          "flex w-full items-center justify-between rounded-md border border-stone-300 bg-stone-100 text-stone-900 outline-none transition-[border-color,box-shadow] duration-150 focus-visible:border-emerald-600 focus-visible:ring-2 focus-visible:ring-emerald-600/25 dark:border-stone-700 dark:bg-stone-950 dark:text-stone-100 dark:focus-visible:border-emerald-400 dark:focus-visible:ring-emerald-400/25",
          SIZE[size],
        )}
      >
        <span className="flex min-w-0 items-center gap-2">
          {icon && (
            <span aria-hidden className="shrink-0 text-stone-500 dark:text-stone-400">
              {icon}
            </span>
          )}
          <span className="truncate">{options[selected]}</span>
        </span>
        <motion.svg
          animate={{ rotate: open ? 180 : 0 }}
          transition={shouldReduceMotion ? { duration: 0 } : { type: "spring", stiffness: 500, damping: 30 }}
          viewBox="0 0 24 24"
          width="16"
          height="16"
          fill="none"
          stroke="currentColor"
          strokeWidth="2"
          strokeLinecap="round"
          strokeLinejoin="round"
          aria-hidden
          className="shrink-0 text-stone-500"
        >
          <path d="m6 9 6 6 6-6" />
        </motion.svg>
      </button>

      <AnimatePresence>
        {open && (
          <motion.div
            initial={shouldReduceMotion ? { opacity: 0 } : { opacity: 0, y: -4, scale: 0.98 }}
            animate={{ opacity: 1, y: 0, scale: 1 }}
            exit={{ opacity: 0 }}
            style={{ transformOrigin: "top" }}
            transition={
              shouldReduceMotion
                ? { duration: 0 }
                : { duration: 0.18, ease: [0.22, 1, 0.36, 1] }
            }
            className={cx(
              "z-20 mt-1.5 min-w-full overflow-hidden rounded-lg border border-stone-200 bg-white shadow-[0_1px_2px_-1px_rgba(0,0,0,0.06),0_4px_12px_-4px_rgba(0,0,0,0.08)] dark:border-stone-700 dark:bg-stone-800 dark:shadow-none",
              // A form select takes its own width and pushes what is under it
              // down; a toolbar select floats over the content beneath.
              size === "sm" && "absolute w-max",
              size === "sm" && (align === "end" ? "right-0" : "left-0"),
            )}
          >
            <ul
              id={`${uid}-listbox`}
              role="listbox"
              aria-label={label}
              aria-activedescendant={`${uid}-option-${highlighted}`}
              data-lenis-prevent
              className="scrollbar-thin max-h-48 overflow-y-auto overscroll-contain p-1"
            >
              {options.map((option, i) => (
                <motion.li
                  key={option}
                  id={`${uid}-option-${i}`}
                  role="option"
                  aria-selected={selected === i}
                  initial={shouldReduceMotion ? { opacity: 1 } : { opacity: 0, x: -4 }}
                  animate={{ opacity: 1, x: 0 }}
                  transition={{ delay: shouldReduceMotion ? 0 : i * 0.03, duration: 0.15 }}
                  onMouseEnter={() => setHighlighted(i)}
                  onClick={() => choose(i)}
                  className={cx("relative cursor-pointer rounded-md px-3 py-2", size === "sm" ? "text-xs" : "text-sm")}
                >
                  {highlighted === i && (
                    <motion.span
                      layoutId={`${uid}-highlight`}
                      className="absolute inset-0 rounded-md bg-stone-100 dark:bg-stone-700"
                      transition={shouldReduceMotion ? { duration: 0 } : { type: "spring", stiffness: 600, damping: 40 }}
                    />
                  )}
                  <span
                    className={cx(
                      "relative flex items-center justify-between gap-4",
                      highlighted === i ? "text-stone-900 dark:text-stone-100" : "text-stone-700 dark:text-stone-300",
                    )}
                  >
                    {option}
                    {selected === i && <span aria-hidden className="text-emerald-700 dark:text-emerald-400">✓</span>}
                  </span>
                </motion.li>
              ))}
            </ul>
          </motion.div>
        )}
      </AnimatePresence>
    </div>
  );
}

"use client";

import { useEffect, useRef, useState } from "react";
import { AnimatePresence, motion, useReducedMotion } from "framer-motion";
import { MagnifyingGlassIcon, XIcon, SpinnerGapIcon } from "@phosphor-icons/react";

const cx = (...c: Array<string | false | null | undefined>) => c.filter(Boolean).join(" ");

interface SearchInputProps {
  value: string;
  onChange: (value: string) => void;
  /** Called after debounceMs of no typing. */
  onSearch?: (value: string) => void;
  debounceMs?: number;
  loading?: boolean;
  placeholder?: string;
  /** A single key (e.g. "/") that focuses the field from anywhere on the page. */
  shortcut?: string;
  /** Renders a "N results" pill on the right when set and the field is non-empty. */
  resultCount?: number;
  ariaLabel?: string;
}

export function SearchInput({
  value,
  onChange,
  onSearch,
  debounceMs = 300,
  loading = false,
  placeholder = "Search",
  shortcut,
  resultCount,
  ariaLabel = "Search",
}: SearchInputProps) {
  const reduce = useReducedMotion();
  const inputRef = useRef<HTMLInputElement>(null);
  const [focused, setFocused] = useState(false);

  const onSearchRef = useRef(onSearch);
  useEffect(() => {
    onSearchRef.current = onSearch;
  }, [onSearch]);

  useEffect(() => {
    if (!onSearchRef.current) return;
    const id = setTimeout(() => onSearchRef.current?.(value), debounceMs);
    return () => clearTimeout(id);
  }, [value, debounceMs]);

  useEffect(() => {
    if (!shortcut) return;
    const onKey = (e: KeyboardEvent) => {
      const el = document.activeElement;
      const typing =
        el instanceof HTMLInputElement ||
        el instanceof HTMLTextAreaElement ||
        (el instanceof HTMLElement && el.isContentEditable);
      if (e.key === shortcut && !typing) {
        e.preventDefault();
        inputRef.current?.focus();
      }
    };
    document.addEventListener("keydown", onKey);
    return () => document.removeEventListener("keydown", onKey);
  }, [shortcut]);

  const showClear = value.length > 0;
  const showHint = !!shortcut && !focused && value.length === 0;

  return (
    <div
      className={cx(
        "flex h-10 w-full items-center gap-2 rounded-md border bg-stone-100 px-2.5 text-sm transition-[border-color,box-shadow] duration-150 dark:bg-stone-950",
        focused
          ? "border-emerald-600 ring-2 ring-emerald-600/25 dark:border-emerald-400 dark:ring-emerald-400/25"
          : "border-stone-300 dark:border-stone-700",
      )}
    >
      <span className="relative h-4 w-4 shrink-0 text-stone-500">
        <AnimatePresence mode="wait" initial={false}>
          {loading ? (
            <motion.span
              key="spin"
              initial={reduce ? {} : { opacity: 0, rotate: -90 }}
              animate={reduce ? {} : { opacity: 1, rotate: 0 }}
              exit={reduce ? {} : { opacity: 0 }}
              className="absolute inset-0 text-emerald-700 dark:text-emerald-400"
            >
              <motion.span
                className="block"
                animate={reduce ? {} : { rotate: 360 }}
                transition={{ duration: 0.8, repeat: Infinity, ease: "linear" }}
              >
                <SpinnerGapIcon size={16} weight="bold" aria-hidden />
              </motion.span>
            </motion.span>
          ) : (
            <motion.span
              key="glass"
              initial={reduce ? {} : { opacity: 0, scale: 0.8 }}
              animate={reduce ? {} : { opacity: 1, scale: 1 }}
              exit={reduce ? {} : { opacity: 0 }}
              className="absolute inset-0"
            >
              <MagnifyingGlassIcon size={16} aria-hidden />
            </motion.span>
          )}
        </AnimatePresence>
      </span>

      <input
        ref={inputRef}
        type="search"
        aria-label={ariaLabel}
        value={value}
        placeholder={placeholder}
        onChange={(e) => onChange(e.target.value)}
        onFocus={() => setFocused(true)}
        onBlur={() => setFocused(false)}
        onKeyDown={(e) => {
          if (e.key !== "Escape") return;
          // First Escape clears the field and is consumed here, so a parent
          // results panel stays open. On an empty field it bubbles instead,
          // letting the parent close.
          if (value) {
            e.stopPropagation();
            onChange("");
          }
        }}
        style={{ outline: "none" }}
        className="min-w-0 flex-1 bg-transparent py-1 text-stone-900 placeholder:text-stone-400 [&::-webkit-search-cancel-button]:hidden dark:text-stone-100"
      />

      <AnimatePresence initial={false} mode="popLayout">
        {resultCount != null && value.length > 0 && !loading && (
          <motion.span
            key="count"
            initial={reduce ? { opacity: 0 } : { opacity: 0, y: 4 }}
            animate={{ opacity: 1, y: 0 }}
            exit={reduce ? { opacity: 0 } : { opacity: 0, y: -4 }}
            className="shrink-0 rounded-full bg-stone-100 px-1.5 py-0.5 text-[11px] font-medium tabular-nums text-stone-500 dark:bg-stone-800 dark:text-stone-400"
          >
            {resultCount} {resultCount === 1 ? "result" : "results"}
          </motion.span>
        )}
      </AnimatePresence>

      {showHint && (
        <kbd className="pointer-events-none hidden shrink-0 rounded border border-stone-200 bg-stone-50 px-1.5 py-0.5 font-mono text-[11px] font-medium text-stone-500 sm:block dark:border-stone-700 dark:bg-stone-900 dark:text-stone-500">
          {shortcut}
        </kbd>
      )}

      <AnimatePresence initial={false}>
        {showClear && (
          <motion.button
            key="clear"
            type="button"
            aria-label="Clear search"
            onClick={() => {
              onChange("");
              inputRef.current?.focus();
            }}
            initial={reduce ? { opacity: 0 } : { opacity: 0, scale: 0.6 }}
            animate={{ opacity: 1, scale: 1 }}
            exit={reduce ? { opacity: 0 } : { opacity: 0, scale: 0.6 }}
            transition={{ type: "spring", stiffness: 520, damping: 30 }}
            className="flex h-5 w-5 shrink-0 items-center justify-center rounded-full text-stone-500 transition-colors hover:bg-stone-100 hover:text-stone-700 dark:hover:bg-white/10 dark:hover:text-stone-100"
          >
            <XIcon size={12} weight="bold" aria-hidden />
          </motion.button>
        )}
      </AnimatePresence>
    </div>
  );
}

/*
Usage:

const [q, setQ] = useState("");

<SearchInput
  value={q}
  onChange={setQ}
  onSearch={(v) => runQuery(v)}   // debounced
  loading={isFetching}
  shortcut="/"
  resultCount={q ? results.length : undefined}
  placeholder="Search commands"
/>
*/

"use client";

import { useEffect, useLayoutEffect, useRef, useState, type PointerEvent as ReactPointerEvent } from "react";
import { createPortal } from "react-dom";

const cx = (...c: Array<string | false | null | undefined>) => c.filter(Boolean).join(" ");

const clamp = (n: number, lo: number, hi: number) => Math.min(hi, Math.max(lo, n));

const HEX_RE = /^#[0-9a-fA-F]{6}$/;

const PRESETS = [
  "#0f172a", "#ef4444", "#f97316", "#f59e0b", "#22c55e",
  "#14b8a6", "#3b82f6", "#10b981", "#ec4899", "#a8a29e",
];

interface Hsv {
  h: number;
  s: number;
  v: number;
}

function hexToHsv(hex: string): Hsv {
  const n = parseInt(hex.slice(1), 16);
  const r = ((n >> 16) & 255) / 255;
  const g = ((n >> 8) & 255) / 255;
  const b = (n & 255) / 255;
  const max = Math.max(r, g, b);
  const min = Math.min(r, g, b);
  const d = max - min;
  let h = 0;
  if (d !== 0) {
    if (max === r) h = ((g - b) / d) % 6;
    else if (max === g) h = (b - r) / d + 2;
    else h = (r - g) / d + 4;
    h *= 60;
    if (h < 0) h += 360;
  }
  return { h, s: max === 0 ? 0 : d / max, v: max };
}

function hsvToHex(h: number, s: number, v: number) {
  const c = v * s;
  const x = c * (1 - Math.abs(((h / 60) % 2) - 1));
  const m = v - c;
  let r = 0;
  let g = 0;
  let b = 0;
  if (h < 60) {
    r = c;
    g = x;
  } else if (h < 120) {
    r = x;
    g = c;
  } else if (h < 180) {
    g = c;
    b = x;
  } else if (h < 240) {
    g = x;
    b = c;
  } else if (h < 300) {
    r = x;
    b = c;
  } else {
    r = c;
    b = x;
  }
  const to = (val: number) => Math.round((val + m) * 255).toString(16).padStart(2, "0");
  return "#" + to(r) + to(g) + to(b);
}

export interface ColorPickerProps {
  value: string;
  onChange: (hex: string) => void;
  /** Accessible name for the trigger. */
  label?: string;
  className?: string;
  /** Replaces the default swatch trigger styling (h-5 w-5 rounded ring). */
  triggerClassName?: string;
  /**
   * Quick picks under the hex field. Defaults to a ten-hue set; pass the
   * colours already in use (so a board stays consistent without forcing a
   * palette on anyone), or an empty array to hide the row.
   */
  swatches?: string[];
}

/**
 * The popover is portalled to the body, which puts it outside any local theme
 * scope (a template with its own light/dark switch). Read the nearest scope
 * off the trigger when opening and repeat it on a wrapper around the portal.
 */
function themeScope(el: HTMLElement | null): "dark" | "light" | null {
  const host = el?.closest("[data-light], .dark");
  if (!host) return null;
  return host.hasAttribute("data-light") ? "light" : "dark";
}

export function ColorPicker({
  value,
  onChange,
  label = "Colour",
  className,
  triggerClassName,
  swatches = PRESETS,
}: ColorPickerProps) {
  const rootRef = useRef<HTMLDivElement>(null);
  const triggerRef = useRef<HTMLButtonElement>(null);
  const popRef = useRef<HTMLDivElement>(null);
  const svRef = useRef<HTMLDivElement>(null);
  const hueRef = useRef<HTMLDivElement>(null);
  const [open, setOpen] = useState(false);
  const [scope, setScope] = useState<"dark" | "light" | null>(null);
  const [pos, setPos] = useState<{ top: number; left: number } | null>(null);
  const [hsv, setHsv] = useState<Hsv>(() => hexToHsv(value));
  const [hexDraft, setHexDraft] = useState(value);

  // Resync from an external value change, but not from our own onChange echo
  // (which would lose hue at s or v === 0).
  useEffect(() => {
    if (hsvToHex(hsv.h, hsv.s, hsv.v).toLowerCase() !== value.toLowerCase()) {
      setHsv(hexToHsv(value));
    }
    setHexDraft(value);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [value]);

  useEffect(() => {
    if (!open) return;
    function onDoc(e: MouseEvent) {
      const t = e.target as Node;
      if (!rootRef.current?.contains(t) && !popRef.current?.contains(t)) setOpen(false);
    }
    function onKey(e: KeyboardEvent) {
      if (e.key === "Escape") setOpen(false);
    }
    document.addEventListener("mousedown", onDoc);
    document.addEventListener("keydown", onKey);
    return () => {
      document.removeEventListener("mousedown", onDoc);
      document.removeEventListener("keydown", onKey);
    };
  }, [open]);

  // The popover renders in a portal at the document root so it is never clipped
  // by an ancestor's overflow or paint containment. Its z-index sits above any
  // app overlay for the same reason: a picker opened from inside a full-screen
  // sheet or dialog has to land on top of it, not behind it. Position it against the
  // trigger each frame it could move, flipping above when there is no room below.
  useLayoutEffect(() => {
    if (!open) return;
    function place() {
      const t = triggerRef.current?.getBoundingClientRect();
      if (!t) return;
      const gap = 8;
      const ph = popRef.current?.offsetHeight ?? 280;
      const pw = popRef.current?.offsetWidth ?? 224;
      const below = window.innerHeight - t.bottom;
      const flip = below < ph + gap && t.top > below;
      const top = flip ? Math.max(gap, t.top - gap - ph) : t.bottom + gap;
      const left = clamp(t.left, gap, Math.max(gap, window.innerWidth - pw - gap));
      setPos({ top, left });
    }
    place();
    window.addEventListener("resize", place);
    window.addEventListener("scroll", place, true);
    return () => {
      window.removeEventListener("resize", place);
      window.removeEventListener("scroll", place, true);
    };
  }, [open]);

  useEffect(() => {
    if (!open) setPos(null);
  }, [open]);

  function commit(next: Hsv) {
    setHsv(next);
    onChange(hsvToHex(next.h, next.s, next.v));
  }

  function svFromEvent(clientX: number, clientY: number) {
    const r = svRef.current?.getBoundingClientRect();
    if (!r) return;
    commit({
      ...hsv,
      s: clamp((clientX - r.left) / r.width, 0, 1),
      v: clamp(1 - (clientY - r.top) / r.height, 0, 1),
    });
  }
  function hueFromEvent(clientX: number) {
    const r = hueRef.current?.getBoundingClientRect();
    if (!r) return;
    commit({ ...hsv, h: clamp(((clientX - r.left) / r.width) * 360, 0, 359.9) });
  }

  function dragSV(e: ReactPointerEvent) {
    e.currentTarget.setPointerCapture(e.pointerId);
    svFromEvent(e.clientX, e.clientY);
  }
  function dragHue(e: ReactPointerEvent) {
    e.currentTarget.setPointerCapture(e.pointerId);
    hueFromEvent(e.clientX);
  }

  function onHexInput(v: string) {
    setHexDraft(v);
    const withHash = v.startsWith("#") ? v : "#" + v;
    if (HEX_RE.test(withHash)) {
      const lower = withHash.toLowerCase();
      setHsv(hexToHsv(lower));
      onChange(lower);
    }
  }

  const hueHex = hsvToHex(hsv.h, 1, 1);

  return (
    <div ref={rootRef} className={cx("inline-block", className)}>
      <button
        ref={triggerRef}
        type="button"
        onClick={() => {
          setScope(themeScope(triggerRef.current));
          setOpen((o) => !o);
        }}
        aria-haspopup="dialog"
        aria-expanded={open}
        aria-label={label + ", " + value.toUpperCase()}
        className={
          triggerClassName ??
          "h-5 w-5 rounded ring-1 ring-black/10 transition-transform hover:scale-110 dark:ring-white/20"
        }
        style={{ background: value }}
      />

      {open && typeof document !== "undefined"
        ? createPortal(
        <div className={scope === "dark" ? "dark" : undefined} data-light={scope === "light" ? "" : undefined}>
        <div
          ref={popRef}
          data-color-picker=""
          role="dialog"
          aria-label={label + " picker"}
          className="fixed z-[100] w-56 rounded-xl border border-stone-200 bg-white p-3 shadow-[0_1px_2px_-1px_rgba(0,0,0,0.06),0_4px_12px_-4px_rgba(0,0,0,0.08)] dark:shadow-none dark:border-stone-700 dark:bg-stone-900"
          style={{ top: pos?.top ?? -9999, left: pos?.left ?? -9999, visibility: pos ? "visible" : "hidden" }}
        >
          <div
            ref={svRef}
            role="slider"
            tabIndex={0}
            aria-label="Saturation and brightness"
            aria-valuemin={0}
            aria-valuemax={100}
            aria-valuenow={Math.round(hsv.s * 100)}
            aria-valuetext={
              Math.round(hsv.s * 100) + " percent saturation, " + Math.round(hsv.v * 100) + " percent brightness"
            }
            onPointerDown={dragSV}
            onPointerMove={(e) => e.currentTarget.hasPointerCapture(e.pointerId) && svFromEvent(e.clientX, e.clientY)}
            onKeyDown={(e) => {
              const d = e.shiftKey ? 0.1 : 0.02;
              const keys = ["ArrowRight", "ArrowLeft", "ArrowUp", "ArrowDown"];
              if (!keys.includes(e.key)) return;
              e.preventDefault();
              if (e.key === "ArrowRight") commit({ ...hsv, s: clamp(hsv.s + d, 0, 1) });
              else if (e.key === "ArrowLeft") commit({ ...hsv, s: clamp(hsv.s - d, 0, 1) });
              else if (e.key === "ArrowUp") commit({ ...hsv, v: clamp(hsv.v + d, 0, 1) });
              else commit({ ...hsv, v: clamp(hsv.v - d, 0, 1) });
            }}
            className="relative h-32 w-full cursor-crosshair touch-none rounded-lg outline-none ring-stone-900/50 focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-emerald-600 dark:focus-visible:outline-emerald-400 dark:ring-white/60"
            style={{
              background: "linear-gradient(to top, #000, transparent), linear-gradient(to right, #fff, " + hueHex + ")",
            }}
          >
            <span
              aria-hidden
              className="absolute h-3.5 w-3.5 -translate-x-1/2 -translate-y-1/2 rounded-full border-2 border-white shadow"
              style={{ left: hsv.s * 100 + "%", top: (1 - hsv.v) * 100 + "%", background: value }}
            />
          </div>

          <div
            ref={hueRef}
            role="slider"
            tabIndex={0}
            aria-label="Hue"
            aria-valuemin={0}
            aria-valuemax={360}
            aria-valuenow={Math.round(hsv.h)}
            onPointerDown={dragHue}
            onPointerMove={(e) => e.currentTarget.hasPointerCapture(e.pointerId) && hueFromEvent(e.clientX)}
            onKeyDown={(e) => {
              const d = e.shiftKey ? 20 : 2;
              if (e.key === "ArrowRight" || e.key === "ArrowUp") {
                e.preventDefault();
                commit({ ...hsv, h: (hsv.h + d) % 360 });
              } else if (e.key === "ArrowLeft" || e.key === "ArrowDown") {
                e.preventDefault();
                commit({ ...hsv, h: (hsv.h - d + 360) % 360 });
              }
            }}
            className="relative mt-3 h-3 w-full cursor-pointer touch-none rounded-full outline-none ring-stone-900/50 focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-emerald-600 dark:focus-visible:outline-emerald-400 dark:ring-white/60"
            style={{
              background: "linear-gradient(to right, #f00 0%, #ff0 17%, #0f0 33%, #0ff 50%, #00f 67%, #f0f 83%, #f00 100%)",
            }}
          >
            <span
              aria-hidden
              className="absolute top-1/2 h-4 w-4 -translate-x-1/2 -translate-y-1/2 rounded-full border-2 border-white shadow"
              style={{ left: (hsv.h / 360) * 100 + "%", background: hueHex }}
            />
          </div>

          <div className="mt-3 flex items-center gap-2">
            <span className="h-6 w-6 shrink-0 rounded ring-1 ring-black/10 dark:ring-white/15" style={{ background: value }} />
            <input
              value={hexDraft.toUpperCase()}
              onChange={(e) => onHexInput(e.target.value)}
              onBlur={() => setHexDraft(value)}
              spellCheck={false}
              aria-label="Hex value"
              className="w-full rounded-md border border-stone-200 bg-transparent px-2 py-1 font-mono text-[11px] uppercase text-stone-700 outline-none focus:border-stone-400 dark:border-stone-700 dark:text-stone-200"
            />
          </div>

          {swatches.length > 0 && (
          <div className="mt-2 flex flex-wrap gap-1.5">
            {swatches.map((p) => (
              <button
                key={p}
                type="button"
                onClick={() => {
                  setHsv(hexToHsv(p));
                  onChange(p);
                }}
                aria-label={"Use " + p}
                className="h-4 w-4 rounded ring-1 ring-black/10 transition-transform hover:scale-110 dark:ring-white/15"
                style={{ background: p }}
              />
            ))}
          </div>
          )}
        </div>
        </div>,
        document.body
      )
        : null}
    </div>
  );
}

