"use client";

import type { CSSProperties, ReactNode } from "react";
import { Check, X } from "lucide-react";

const cx = (...c: Array<string | false | null | undefined>) => c.filter(Boolean).join(" ");

/**
 * Every colour below is derived in CSS from the one hex the user picked, so
 * there is no contrast maths in JS, nothing to disagree about between the
 * server and the browser, and a colour chosen at runtime is readable the
 * moment it lands.
 *
 * - The fill is the hue mixed into the surface (14% on white, 20% on the
 *   stone-900 card), so a saturated pick never becomes a solid block.
 * - The text is the same hue with its OKLCH lightness clamped: at most 0.45
 *   on light (about 6:1 on the tint or better) and at least 0.82 on dark
 *   (about 5.5:1 or better). A pale yellow and a near-black both come out
 *   readable, which is the case a user-picked palette always ends up with.
 * - Browsers without relative colour syntax drop the text colour and inherit
 *   the surrounding text, which is still legible, just not tinted.
 */
function chipVars(color: string): CSSProperties {
  return {
    "--chip": color,
    "--chip-bg": `color-mix(in oklab, ${color} 14%, #ffffff)`,
    "--chip-bg-on": `color-mix(in oklab, ${color} 26%, #ffffff)`,
    "--chip-line": `color-mix(in oklab, ${color} 36%, #ffffff)`,
    "--chip-fg": `oklch(from ${color} min(l, 0.45) min(c, 0.16) h)`,
    "--chip-bg-dark": `color-mix(in oklab, ${color} 20%, #1c1917)`,
    "--chip-bg-on-dark": `color-mix(in oklab, ${color} 34%, #1c1917)`,
    "--chip-line-dark": `color-mix(in oklab, ${color} 42%, #1c1917)`,
    "--chip-fg-dark": `oklch(from ${color} max(l, 0.82) min(c, 0.12) h)`,
  } as CSSProperties;
}

const SIZE = {
  sm: "h-5 gap-1 px-2 text-[11px]",
  md: "h-6 gap-1.5 px-2.5 text-xs",
} as const;

const SURFACE =
  "border bg-[var(--chip-bg)] border-[color:var(--chip-line)] text-[color:var(--chip-fg)] dark:bg-[var(--chip-bg-dark)] dark:border-[color:var(--chip-line-dark)] dark:text-[color:var(--chip-fg-dark)]";

const FOCUS =
  "focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-emerald-600 dark:focus-visible:outline-emerald-400";

export interface LabelChipProps {
  /** Any CSS colour, usually a hex the user picked. */
  color: string;
  children: ReactNode;
  size?: "sm" | "md";
  /** Hide the leading dot, e.g. in a dense row where the fill already carries the hue. */
  dot?: boolean;
  /** Turns the chip into a toggle button (a filter). */
  pressed?: boolean;
  onPressedChange?: (pressed: boolean) => void;
  /** Adds a remove button after the name. */
  onRemove?: () => void;
  className?: string;
}

/**
 * A label in a colour the user chose, not one from a fixed palette. Static by
 * default; a toggle when given `onPressedChange`; removable with `onRemove`.
 */
export function LabelChip({
  color,
  children,
  size = "md",
  dot = true,
  pressed,
  onPressedChange,
  onRemove,
  className,
}: LabelChipProps) {
  const style = chipVars(color);
  const toggle = onPressedChange !== undefined;
  const body = (
    <>
      {dot && (
        <span
          aria-hidden
          className="h-1.5 w-1.5 shrink-0 rounded-full bg-[var(--chip)] ring-1 ring-inset ring-black/15 dark:ring-white/25"
        />
      )}
      <span className="truncate">{children}</span>
      {toggle && pressed && <Check aria-hidden className="h-3 w-3 shrink-0" strokeWidth={2.5} />}
    </>
  );

  const base = cx(
    "inline-flex max-w-full shrink-0 items-center rounded-full font-medium leading-none",
    SIZE[size],
    SURFACE,
    className
  );

  if (toggle) {
    return (
      <button
        type="button"
        aria-pressed={!!pressed}
        onClick={() => onPressedChange(!pressed)}
        style={style}
        className={cx(
          base,
          "transition-[background-color,box-shadow] duration-150 active:scale-[0.98]",
          pressed
            ? "bg-[var(--chip-bg-on)] shadow-[inset_0_0_0_1px_var(--chip-fg)] dark:bg-[var(--chip-bg-on-dark)] dark:shadow-[inset_0_0_0_1px_var(--chip-fg-dark)]"
            : "hover:bg-[var(--chip-bg-on)] dark:hover:bg-[var(--chip-bg-on-dark)]",
          FOCUS
        )}
      >
        {body}
      </button>
    );
  }

  return (
    <span style={style} className={cx(base, onRemove && "pr-1")}>
      {body}
      {onRemove && (
        <button
          type="button"
          onClick={onRemove}
          aria-label={`Remove ${typeof children === "string" ? children : "label"}`}
          className={cx(
            "-my-1 ml-0.5 inline-flex h-4 w-4 items-center justify-center rounded-full opacity-70 transition-opacity duration-150 hover:opacity-100",
            FOCUS
          )}
        >
          <X aria-hidden className="h-3 w-3" strokeWidth={2.5} />
        </button>
      )}
    </span>
  );
}

