                          )}
                        </span>
                        <span className="whitespace-nowrap text-xs font-medium text-white dark:text-stone-900">
                          {person.name}
                        </span>
                      </div>
                    ))}
                  </div>
                  <span
                    aria-hidden
                    className="absolute left-1/2 top-full h-2 w-2 -translate-x-1/2 -translate-y-1/2 rotate-45 bg-stone-900 dark:bg-stone-100"
