// A sprint is a start and an end date, on any weekday. Sprints never overlap,
// but they may leave days between them (a holiday week, a hardening week), and
// those days belong to no sprint. The newest sprint runs to the later of its
// end and today: a team that forgets to start the next one still sees today's
// commits land somewhere.
const PLANNED_DAYS = 14;
// The longest sprint the date fields accept.
const MAX_SPRINT_DAYS = 56;
// A year of history, five sprints on screen at a time.
const SEEDED_SPRINTS = 26;
const VISIBLE_SPRINTS = 5;
// How far ahead a sprint can be scheduled when it is created early.
const MAX_LEAD_DAYS = 28;
const DAY_MS = 86_400_000;
const DAYS = 7;
const WEEKDAYS = ["Sunday", "Monday", "Tuesday", "Wednesday", "Thursday", "Friday", "Saturday"];
const MONTHS = ["Jan", "Feb", "Mar", "Apr", "May", "Jun", "Jul", "Aug", "Sep", "Oct", "Nov", "Dec"];
const COMMITS_KEY = "ui-commit-graph:commits";
const SPRINTS_KEY = "ui-commit-graph:sprints";
const THEME_KEY = "ui-commit-graph:theme";
// The server cannot know what day it is for the viewer, so the first paint
// renders against a fixed date and the client swaps in the real one during
// hydration (see useToday).
const SERVER_TODAY = "2026-09-29";

type ThemeId = "emerald" | "blue" | "violet" | "amber" | "rose";

interface Theme {
  label: string;
  swatch: string;
  light: [string, string, string, string];
  dark: [string, string, string, string];
}

const THEMES: Record<ThemeId, Theme> = {
  emerald: { label: "Emerald", swatch: "#16A34A", light: ["#BBF7D0", "#4ADE80", "#16A34A", "#166534"], dark: ["#14532D", "#15803D", "#22C55E", "#86EFAC"] },
  blue: { label: "Blue", swatch: "#2563EB", light: ["#BFDBFE", "#60A5FA", "#2563EB", "#1E3A8A"], dark: ["#1E3A8A", "#1D4ED8", "#3B82F6", "#93C5FD"] },
  violet: { label: "Violet", swatch: "#7C3AED", light: ["#DDD6FE", "#A78BFA", "#7C3AED", "#4C1D95"], dark: ["#4C1D95", "#6D28D9", "#8B5CF6", "#C4B5FD"] },
  amber: { label: "Amber", swatch: "#D97706", light: ["#FDE68A", "#FBBF24", "#D97706", "#92400E"], dark: ["#78350F", "#B45309", "#F59E0B", "#FCD34D"] },
  rose: { label: "Rose", swatch: "#DB2777", light: ["#FBCFE8", "#F472B6", "#DB2777", "#831843"], dark: ["#831843", "#BE185D", "#EC4899", "#F9A8D4"] },
};

const THEME_IDS = Object.keys(THEMES) as ThemeId[];

// Dates are handled as whole UTC day numbers (days since 1970-01-01). Adding a
// day is adding one, and no daylight-saving change can make a day 23 hours long.
function dayNumber(iso: string): number {
  const [y, m, d] = iso.split("-").map(Number);
  return Math.round(Date.UTC(y, m - 1, d) / DAY_MS);
}

function isoFromDay(day: number): string {
  return new Date(day * DAY_MS).toISOString().slice(0, 10);
}

function weekdayOf(day: number): number {
  return new Date(day * DAY_MS).getUTCDay();
}

// Month names by hand rather than toLocaleDateString: the server and the
// browser can disagree on locale, and text that differs between them is a
// hydration error.
function shortDate(day: number): string {
  const d = new Date(day * DAY_MS);
  return `${MONTHS[d.getUTCMonth()]} ${d.getUTCDate()}`;
}

function longDate(day: number): string {
  return `${WEEKDAYS[weekdayOf(day)].slice(0, 3)}, ${shortDate(day)}`;
}

function relativeDay(day: number, today: number): string {
  const diff = day - today;
  if (diff === 0) return "today";
  if (diff === -1) return "yesterday";
  if (diff === 1) return "tomorrow";
  return diff < 0 ? `${-diff} days ago` : `in ${diff} days`;
}

// Pure function of the calendar date, not of when the page is viewed: Sep 24
// has the same count today and next month. Weekends run at a third, so the
// weekday axis carries a real signal.
function seededCount(day: number): number {
  const x = Math.sin((day + 11) * 12.9898 + 78.233) * 43758.5453;
  const frac = x - Math.floor(x);
  let count = 0;
  if (frac > 0.94) count = 8 + (Math.floor(frac * 37) % 6);
  else if (frac > 0.78) count = 4 + (Math.floor(frac * 23) % 4);
  else if (frac > 0.35) count = 1 + (Math.floor(frac * 17) % 3);
  return weekdayOf(day) % 6 === 0 ? Math.floor(count / 3) : count;
}

// Integer hash (Math.imul, exact in every engine), deliberately not the
// sin-based seededCount above. A bucketed level survives a 1-ULP difference
// between two engines' Math.sin; a message index or a SHA does not, and text
// that differs between the server and the client is a hydration error.
function hash32(seed: number): number {
  let h = Math.imul(seed ^ 0x9e3779b9, 0x85ebca6b);
  h ^= h >>> 13;
  h = Math.imul(h, 0xc2b2ae35);
  h ^= h >>> 16;
  return h >>> 0;
}

interface SprintRange {
  start: number;
  end: number;
}

// The demo's history: 26 back-to-back sprints of 12 to 16 days, the newest
// started five days ago. Uneven lengths put every sprint on a different
// weekday, which is what real teams get once a holiday or a slipped planning
// meeting has moved the start once or twice.
function seededRanges(today: number): SprintRange[] {
  const starts = [today - 5];
  for (let i = 1; i < SEEDED_SPRINTS; i++) {
    starts.unshift(starts[0] - (12 + (hash32(i * 131 + 17) % 5)));
  }
  return starts.map((start, i) => ({ start, end: i < starts.length - 1 ? starts[i + 1] - 1 : start + PLANNED_DAYS - 1 }));
}

// A real deploy reads these from the git log (or the host's API). They are
// generated here for the same reason the counts are: the site is a static
// export, so the demo has to carry its own history.
