interface Commit {
  sha: string;
  time: string;
  subject: string;
}

// Every stride is coprime with SUBJECTS.length, so walking the pool by one of
// them visits every subject before repeating: a day never lands the same commit
// message twice, which is what gives a hashed message away as fake.
const STRIDES = [7, 11, 13, 17, 19, 23];

function commitsFor(day: number, count: number): Commit[] {
  const base = hash32(day * 31 + 7) % SUBJECTS.length;
  const stride = STRIDES[hash32(day * 17 + 5) % STRIDES.length];
  return Array.from({ length: count }, (_, i) => {
    const h = hash32(day * 97 + i * 7919 + 3);
    return { h, minutes: 8 * 60 + (h % 660) };
  })
    .sort((a, b) => a.minutes - b.minutes)
    .map(({ h, minutes }, i) => ({
      sha: h.toString(16).padStart(8, "0").slice(0, 7),
      time: `${String(Math.floor(minutes / 60)).padStart(2, "0")}:${String(minutes % 60).padStart(2, "0")}`,
      subject: SUBJECTS[(base + i * stride) % SUBJECTS.length],
    }));
}

function levelFor(count: number): 0 | 1 | 2 | 3 | 4 {
  if (count <= 0) return 0;
  if (count <= 2) return 1;
  if (count <= 5) return 2;
  if (count <= 9) return 3;
  return 4;
}

interface Day {
  day: number;
  count: number;
  upcoming: boolean;
}

interface Sprint {
  start: number;
  end: number;
  days: Day[];
  status: "done" | "current" | "planned";
  overBy: number;
  total: number;
  activeDays: number;
  elapsedDays: number;
  best: number;
}

// Where the newest sprint actually ends: its own end, or today if it has run
// past that with nothing started after it.
function effectiveEnd(range: SprintRange, isNewest: boolean, today: number): number {
  return isNewest && range.start <= today ? Math.max(range.end, today) : range.end;
}

function buildSprints(ranges: SprintRange[], today: number, extra: Record<string, number>): Sprint[] {
  return ranges.map((range, i) => {
    const { start } = range;
    const isNewest = i === ranges.length - 1;
    const end = effectiveEnd(range, isNewest, today);
    const days: Day[] = [];
    for (let day = start; day <= end; day++) {
      const upcoming = day > today;
      days.push({ day, upcoming, count: upcoming ? 0 : seededCount(day) + (extra[isoFromDay(day)] ?? 0) });
    }
    const elapsed = days.filter((d) => !d.upcoming);
    return {
      start,
      end,
      days,
      status: start > today ? "planned" : end < today ? "done" : "current",
      overBy: end - range.end,
      total: elapsed.reduce((sum, d) => sum + d.count, 0),
      activeDays: elapsed.filter((d) => d.count > 0).length,
      elapsedDays: elapsed.length,
      best: elapsed.reduce((max, d) => Math.max(max, d.count), 0),
    };
  });
}

// The overview lays each sprint on the calendar, GitHub-style: rows are Sunday
// to Saturday, so a sprint that starts on a Wednesday opens three cells down
// its first column. Nulls pad the partial weeks at either end.
function calendarColumns(days: Day[]): (Day | null)[][] {
  const cells: (Day | null)[] = [...Array<null>(weekdayOf(days[0].day)).fill(null), ...days];
  while (cells.length % DAYS) cells.push(null);
  return Array.from({ length: cells.length / DAYS }, (_, c) => cells.slice(c * DAYS, (c + 1) * DAYS));
}

// The detail view counts from the sprint's own first day instead, so a
// Wednesday sprint reads Wed to Tue across the top and two full rows down.
function sprintRows(days: Day[]): (Day | null)[][] {
  return Array.from({ length: Math.ceil(days.length / DAYS) }, (_, r) => {
    const row: (Day | null)[] = days.slice(r * DAYS, (r + 1) * DAYS);
    while (row.length < DAYS) row.push(null);
    return row;
  });
}

const ISO_DATE = /^\d{4}-\d{2}-\d{2}$/;

function parseDate(value: unknown): number | null {
  return typeof value === "string" && ISO_DATE.test(value) ? dayNumber(value) : null;
}

// Stored as [{ start, end }] in ISO dates. Anything overlapping the sprint
// before it is dropped rather than guessed at, so a hand-edited value can
// never produce two sprints claiming the same day.
function parseRanges(raw: string | null): SprintRange[] | null {
  if (!raw) return null;
  try {
    const list: unknown = JSON.parse(raw);
    if (!Array.isArray(list)) return null;
    const ranges = list
      .map((item: unknown) => {
        const { start, end } = (item ?? {}) as { start?: unknown; end?: unknown };
        const s = parseDate(start);
        const e = parseDate(end);
        return s !== null && e !== null && e >= s ? { start: s, end: e } : null;
      })
      .filter((r): r is SprintRange => r !== null)
      .sort((a, b) => a.start - b.start)
      .filter((r, i, all) => i === 0 || r.start > all[i - 1].end);
    return ranges.length > 0 ? ranges : null;
  } catch {
    return null;
  }
}

function parseCommits(raw: string | null): Record<string, number> {
  if (!raw) return {};
  try {
    const map: unknown = JSON.parse(raw);
    return map && typeof map === "object" && !Array.isArray(map) ? (map as Record<string, number>) : {};
  } catch {
    return {};
  }
}

const subscribeNever = () => () => {};

// Read through useSyncExternalStore rather than seeding useState from
// localStorage in an effect: the server snapshot is what both the server and
// the first client paint render, so there's nothing for hydration to disagree
// about, and no cascading setState-in-effect render. Raw strings, not parsed
// values, so the snapshot compares equal between reads.
function readKey(key: string): string | null {
  try {
    return localStorage.getItem(key);
  } catch {
    return null;
  }
}
function getSprintsSnapshot() {
  return readKey(SPRINTS_KEY);
}
function getCommitsSnapshot() {
  return readKey(COMMITS_KEY);
}
function getNullSnapshot() {
  return null;
}

function getThemeSnapshot(): ThemeId {
  const stored = readKey(THEME_KEY) as ThemeId | null;
  return stored && stored in THEMES ? stored : "emerald";
}
function getThemeServerSnapshot(): ThemeId {
  return "emerald";
}

// The viewer's local calendar date, not the UTC one: a commit at 9pm in
// California belongs to that evening, not to tomorrow.
function getTodaySnapshot(): string {
  const d = new Date();
  return `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, "0")}-${String(d.getDate()).padStart(2, "0")}`;
}
function getTodayServerSnapshot(): string {
  return SERVER_TODAY;
}

function writeKey(key: string, value: string | null) {
  try {
    if (value === null) localStorage.removeItem(key);
    else localStorage.setItem(key, value);
  } catch {
    // no-op
  }
}

