// One form for both jobs, creating a sprint and changing an existing sprint's
// dates. A new sprint defaults to starting today because most sprints are
// created the day they start; the fields are there for the ones that are not.
function SprintDatesForm({
  title,
  start,
  end,
  startBounds,
  endBounds,
  today,
  error,
  hint,
  submitLabel,
  onStartChange,
  onEndChange,
  onSubmit,
  onCancel,
}: SprintDatesFormProps) {
  const shouldReduceMotion = useReducedMotion();
  const startRef = useRef<HTMLInputElement | null>(null);
  const id = useId();
  const hintId = `${id}-hint`;
  const todayIso = isoFromDay(today);
  const canPickToday = start !== todayIso && today <= startBounds.max && (startBounds.min === null || today >= startBounds.min);

  useEffect(() => {
    startRef.current?.focus({ preventScroll: true });
  }, []);

  const submit = (event: FormEvent) => {
    event.preventDefault();
    if (!error) onSubmit();
  };

  return (
    <motion.form
      onSubmit={submit}
      aria-label={title}
      initial={shouldReduceMotion ? { opacity: 0 } : { opacity: 0, y: -4 }}
      animate={{ opacity: 1, y: 0 }}
      transition={{ duration: 0.18, ease: [0.16, 1, 0.3, 1] }}
      className="mt-3 rounded-xl border border-stone-200 p-3 dark:border-stone-800"
    >
      <p className="text-sm font-medium text-stone-900 dark:text-stone-100">{title}</p>
      <div className="mt-2 grid grid-cols-2 gap-2">
        <div>
          <div className="flex h-4 items-center justify-between gap-2">
            <label htmlFor={`${id}-start`} className={EYEBROW}>
              Starts
            </label>
            {canPickToday && (
              <button
                type="button"
                onClick={() => onStartChange(todayIso)}
                className={`rounded text-[11px] font-medium text-emerald-700 hover:underline dark:text-emerald-400 ${FOCUS}`}
              >
                Today
              </button>
            )}
          </div>
          <input
            ref={startRef}
            id={`${id}-start`}
            type="date"
            required
            value={start}
            min={startBounds.min === null ? undefined : isoFromDay(startBounds.min)}
            max={isoFromDay(startBounds.max)}
            onChange={(event) => onStartChange(event.target.value)}
            aria-invalid={error?.field === "start" ? true : undefined}
            aria-describedby={hintId}
            className={`mt-1 ${INPUT}`}
          />
        </div>
        <div>
          <div className="flex h-4 items-center">
            <label htmlFor={`${id}-end`} className={EYEBROW}>
              Ends
            </label>
          </div>
          <input
            id={`${id}-end`}
            type="date"
            required
            value={end}
            min={endBounds.min === null ? undefined : isoFromDay(endBounds.min)}
            max={isoFromDay(endBounds.max)}
            onChange={(event) => onEndChange(event.target.value)}
            aria-invalid={error?.field === "end" ? true : undefined}
            aria-describedby={hintId}
            className={`mt-1 ${INPUT}`}
          />
        </div>
      </div>
      <p id={hintId} className={`mt-2 text-xs ${error ? "text-red-600 dark:text-red-400" : "text-stone-600 dark:text-stone-400"}`}>
        {error?.message ?? hint}
      </p>
      <div className="mt-3 flex justify-end gap-2">
        <button
          type="button"
          onClick={onCancel}
          className={`h-8 rounded-md border border-stone-300 px-3 text-xs font-medium text-stone-700 transition-colors duration-150 hover:bg-stone-100 active:scale-[0.98] dark:border-stone-700 dark:text-stone-200 dark:hover:bg-stone-800 ${FOCUS}`}
        >
          Cancel
        </button>
        <button
          type="submit"
          disabled={error !== null}
          className={`h-8 rounded-md bg-emerald-700 px-3 text-xs font-medium text-white transition-colors duration-150 hover:bg-emerald-800 active:scale-[0.98] active:bg-emerald-900 disabled:pointer-events-none disabled:opacity-50 ${FOCUS}`}
        >
          {submitLabel}
        </button>
      </div>
    </motion.form>
  );
}

type Draft = { mode: "create" } | { mode: "edit"; index: number };

export function CommitGraph() {
  const shouldReduceMotion = useReducedMotion();
  const todayIso = useSyncExternalStore(subscribeNever, getTodaySnapshot, getTodayServerSnapshot);
  const persistedSprints = useSyncExternalStore(subscribeNever, getSprintsSnapshot, getNullSnapshot);
  const persistedCommits = useSyncExternalStore(subscribeNever, getCommitsSnapshot, getNullSnapshot);
  const persistedTheme = useSyncExternalStore(subscribeNever, getThemeSnapshot, getThemeServerSnapshot);
  // undefined means "no change this session, use what storage holds"; null
  // means "cleared", which is different from never having been set.
  const [sprintsOverride, setSprintsOverride] = useState<string | null | undefined>(undefined);
  const [commitsOverride, setCommitsOverride] = useState<string | null | undefined>(undefined);
  const [themeOverride, setThemeOverride] = useState<ThemeId | null>(null);
  const [committing, setCommitting] = useState(false);
  const [justCommitted, setJustCommitted] = useState(false);
  const [selected, setSelected] = useState<number | null>(null);
  const [selectedDay, setSelectedDay] = useState<number | null>(null);
  // Counted back from the newest page rather than forward from the oldest, so
  // adding a sprint keeps you on the newest page instead of one behind it.
  const [pagesBack, setPagesBack] = useState(0);
  const [pageDir, setPageDir] = useState(0);
  const [draft, setDraft] = useState<Draft | null>(null);
  const [draftStart, setDraftStart] = useState("");
  const [draftEnd, setDraftEnd] = useState("");
  // A new sprint's end follows its start at the planned length until the end
  // is picked by hand; after that the two move independently.
  const [endTouched, setEndTouched] = useState(false);
  const [announcement, setAnnouncement] = useState("");
  const sprintRefs = useRef<(HTMLButtonElement | null)[]>([]);
  const backRef = useRef<HTMLButtonElement | null>(null);
  const draftTriggerRef = useRef<HTMLButtonElement | null>(null);
  const returnFocusTo = useRef<number | null>(null);
  const focusAfterCreate = useRef<number | null>(null);
  const wasSelected = useRef<number | null>(null);

  const today = dayNumber(todayIso);
  const sprintsRaw = sprintsOverride === undefined ? persistedSprints : sprintsOverride;
  const commitsRaw = commitsOverride === undefined ? persistedCommits : commitsOverride;
  const theme = themeOverride ?? persistedTheme;

  const customRanges = useMemo(() => parseRanges(sprintsRaw), [sprintsRaw]);
  const ranges = useMemo(() => customRanges ?? seededRanges(today), [customRanges, today]);
  const extra = useMemo(() => parseCommits(commitsRaw), [commitsRaw]);
  const sprints = useMemo(() => buildSprints(ranges, today, extra), [ranges, today, extra]);
  const sprintColumns = useMemo(() => sprints.map((sprint) => calendarColumns(sprint.days)), [sprints]);

  const currentIndex = sprints.findIndex((sprint) => sprint.status === "current");
  const current = currentIndex === -1 ? null : sprints[currentIndex];
  const lastIndex = sprints.length - 1;

  const maxStart = Math.max(0, sprints.length - VISIBLE_SPRINTS);
  const windowStart = Math.min(Math.max(maxStart - pagesBack, 0), maxStart);
  const windowEnd = Math.min(windowStart + VISIBLE_SPRINTS, sprints.length);
  const visibleSprints = sprints.slice(windowStart, windowEnd);
  // The window's own total, not the year's: the headline should count what is
  // actually on screen.
  const windowTotal = visibleSprints.reduce((sum, sprint) => sum + sprint.total, 0);
  const atOldest = windowStart === 0;
  const atNewest = windowStart >= maxStart;

  const streak = useMemo(() => {
    let count = 0;
    for (let day = today; day >= ranges[0].start; day--) {
      if (seededCount(day) + (extra[isoFromDay(day)] ?? 0) > 0) count++;
      else break;
    }
    return count;
  }, [today, ranges, extra]);

  const detail = selected === null ? null : (sprints[selected] ?? null);
  const isCurrentSprint = selected !== null && selected === currentIndex;
  const delta =
    selected === null || selected === 0 || detail?.status === "planned" ? null : sprints[selected].total - sprints[selected - 1].total;

  const sprintLog = useMemo(
    () => (detail === null ? [] : detail.days.map((d) => ({ ...d, commits: commitsFor(d.day, d.count) }))),
    [detail],
  );

  const visibleDays = selectedDay === null ? sprintLog.filter((d) => d.count > 0) : sprintLog.filter((d) => d.day === selectedDay);

  // Focus follows the view, in both directions: into the sprint it lands on the
  // way back out, and on return it lands on the sprint you came from rather
  // than at the top of the card.
  useEffect(() => {
    const was = wasSelected.current;
    wasSelected.current = selected;
    if (selected !== null && was === null) {
      backRef.current?.focus({ preventScroll: true });
    } else if (selected !== null && document.activeElement === document.body) {
      // Stepping onto the first or last sprint disables the chevron that was
      // pressed, and a disabled button drops focus to the page.
      backRef.current?.focus({ preventScroll: true });
    } else if (selected === null && was !== null && returnFocusTo.current !== null) {
      sprintRefs.current[returnFocusTo.current]?.focus({ preventScroll: true });
      returnFocusTo.current = null;
    }
  }, [selected]);

  // A new sprint's block only exists after the render that adds it.
  useEffect(() => {
    if (focusAfterCreate.current === null) return;
    sprintRefs.current[focusAfterCreate.current]?.focus({ preventScroll: true });
    focusAfterCreate.current = null;
  }, [sprints]);

  const moveWindowTo = (start: number) => setPagesBack(maxStart - Math.min(Math.max(start, 0), maxStart));

  // Stepping to a sprint also drags the overview window along, so coming back
  // out lands on the sprint you were reading rather than where you started.
  const openSprint = (si: number) => {
    const target = Math.min(Math.max(si, 0), lastIndex);
    returnFocusTo.current = target;
    setSelected(target);
    setSelectedDay(null);
    setDraft(null);
    moveWindowTo(Math.min(Math.max(windowStart, target - VISIBLE_SPRINTS + 1), target));
  };

  const page = (direction: -1 | 1) => {
    setPageDir(direction);
    moveWindowTo(windowStart + direction * VISIBLE_SPRINTS);
  };

  const closeDetail = () => {
    setSelected(null);
    setSelectedDay(null);
    setDraft(null);
  };

  const activeTheme = THEMES[theme];
  const ramp = (level: 0 | 1 | 2 | 3 | 4, isDark: boolean) => (level === 0 ? null : (isDark ? activeTheme.dark : activeTheme.light)[level - 1]);

  const changeTheme = (id: ThemeId) => {
    setThemeOverride(id);
    writeKey(THEME_KEY, id);
  };

  const saveRanges = (next: SprintRange[]) => {
    const raw = JSON.stringify(next.map((r) => ({ start: isoFromDay(r.start), end: isoFromDay(r.end) })));
    writeKey(SPRINTS_KEY, raw);
    setSprintsOverride(raw);
  };

  const handleCommit = () => {
    if (committing) return;
    setCommitting(true);
    // A real deploy of this component would POST to /api/commits and read the
    // updated count back; this demo simulates that round trip's latency and
    // persists the result the same place a server response would end up
    // caching to, so the count survives a reload without a real backend.
    // Keyed by date, so tomorrow's commits land on tomorrow.
    const latency = 420 + Math.round(Math.random() * 260);
    window.setTimeout(() => {
      const raw = JSON.stringify({ ...extra, [todayIso]: (extra[todayIso] ?? 0) + 1 });
      writeKey(COMMITS_KEY, raw);
      setCommitsOverride(raw);
      setCommitting(false);
      setJustCommitted(true);
      window.setTimeout(() => setJustCommitted(false), 500);
    }, latency);
  };

  const handleReset = () => {
    writeKey(COMMITS_KEY, null);
    writeKey(SPRINTS_KEY, null);
    setCommitsOverride(null);
    setSprintsOverride(null);
    closeDetail();
    setPagesBack(0);
    setAnnouncement("Sprints and commits reset to the sample history.");
  };

  const draftStartDay = ISO_DATE.test(draftStart) ? dayNumber(draftStart) : null;
  const draftEndDay = ISO_DATE.test(draftEnd) ? dayNumber(draftEnd) : null;
  const newest = ranges[lastIndex];

  // Where each field may land. A new sprint has to start after the newest one
  // starts (otherwise it would swallow it whole) and at most four weeks out.
  // An existing sprint keeps clear of its neighbours: nothing else moves when
  // its dates change, so it can never take days that belong to another sprint.
  const draftLimits = (() => {
    if (draft === null) return null;
    const anchor = draftStartDay ?? (draft.mode === "create" ? today : ranges[draft.index].start);
    const endMax = (next: SprintRange | undefined) => (next ? Math.min(next.start - 1, anchor + MAX_SPRINT_DAYS - 1) : anchor + MAX_SPRINT_DAYS - 1);
    if (draft.mode === "create") {
      return {
        start: { min: newest.start + 1, max: today + MAX_LEAD_DAYS },
        end: { min: draftStartDay, max: endMax(undefined) },
      };
    }
    const i = draft.index;
    const prev = ranges[i - 1];
    const next = ranges[i + 1];
    return {
      start: { min: prev ? prev.end + 1 : null, max: next ? next.start - 1 : today + MAX_LEAD_DAYS },
      end: { min: draftStartDay, max: endMax(next) },
    };
  })();

  // Creating a sprint closes the newest one the day before it starts. If the
  // new one starts later than that, the newest keeps its own end (or today, if
  // it had already run past it) and the days between belong to no sprint.
  const newestEndAfterCreate = (start: number) => {
    const runsTo = effectiveEnd(newest, true, today);
    return start <= runsTo + 1 ? start - 1 : runsTo;
  };

  const draftError = ((): DraftError | null => {
    if (draft === null || draftLimits === null) return null;
    if (draftStartDay === null) return { field: "start", message: "Pick a date for the sprint to start." };
    if (draftEndDay === null) return { field: "end", message: "Pick a date for the sprint to end." };
    const { start, end } = draftLimits;
    const i = draft.mode === "create" ? lastIndex + 1 : draft.index;
    if (start.min !== null && draftStartDay < start.min) {
      return draft.mode === "create"
        ? { field: "start", message: `Has to be after Sprint ${i} starts on ${longDate(start.min - 1)}.` }
        : { field: "start", message: `Sprint ${i} ends ${longDate(start.min - 1)}, so this one can start ${shortDate(start.min)} at the earliest.` };
    }
    if (draftStartDay > start.max) {
      return draft.mode === "edit" && draft.index < lastIndex
        ? { field: "start", message: `Sprint ${i + 2} starts ${longDate(start.max + 1)}, so this one has to start before it.` }
        : { field: "start", message: `Sprints can be scheduled up to four weeks ahead, ${longDate(start.max)} at the latest.` };
    }
    if (draftEndDay < draftStartDay) return { field: "end", message: "The end date is before the start date." };
    const next = draft.mode === "edit" ? ranges[draft.index + 1] : undefined;
    if (next && draftEndDay >= next.start) {
      return { field: "end", message: `Sprint ${i + 2} starts ${longDate(next.start)}, so this one has to end by ${shortDate(next.start - 1)}.` };
    }
    if (draftEndDay > end.max) {
      return { field: "end", message: `Sprints run eight weeks at most, so ${longDate(end.max)} at the latest.` };
    }
    return null;
  })();

  const plural = (n: number, word: string) => `${n} ${word}${n === 1 ? "" : "s"}`;

  // The consequence line. Dates decide more than this sprint's own length: a
  // new sprint closes the one before it, and any sprint can leave days that
  // belong to no sprint. The form says so before anything is saved.
  const draftHint = (() => {
    if (draft === null || draftStartDay === null || draftEndDay === null || draftEndDay < draftStartDay) return null;
    const parts = [`${plural(draftEndDay - draftStartDay + 1, "day")}, starting ${relativeDay(draftStartDay, today)}.`];
    if (draft.mode === "create") {
      const closesOn = newestEndAfterCreate(draftStartDay);
      if (closesOn !== newest.end) {
        const length = closesOn - newest.start + 1;
        parts.push(
          closesOn < today
            ? `Sprint ${lastIndex + 1} closes ${shortDate(closesOn)} after ${plural(length, "day")}.`
            : `Sprint ${lastIndex + 1} now ends ${shortDate(closesOn)}, ${plural(length, "day")} in all.`,
        );
      }
      const gap = draftStartDay - closesOn - 1;
      if (gap > 0) parts.push(`The ${plural(gap, "day")} between them belong to no sprint.`);
    } else {
      const i = draft.index;
      const prev = ranges[i - 1];
      const next = ranges[i + 1];
      const gapBefore = prev ? draftStartDay - prev.end - 1 : 0;
      const gapAfter = next ? next.start - draftEndDay - 1 : 0;
      if (gapBefore > 0) parts.push(`Leaves ${plural(gapBefore, "day")} after Sprint ${i} in no sprint.`);
      if (gapAfter > 0) parts.push(`Leaves ${plural(gapAfter, "day")} before Sprint ${i + 2} in no sprint.`);
      if (!next && draftStartDay <= today && draftEndDay < today) {
        parts.push("It keeps collecting commits past that until the next sprint starts.");
      }
    }
    return parts.join(" ");
  })();

  const openDraft = (next: Draft, trigger: HTMLButtonElement) => {
    draftTriggerRef.current = trigger;
    setDraft(next);
    if (next.mode === "create") {
      setDraftStart(todayIso);
      setDraftEnd(isoFromDay(today + PLANNED_DAYS - 1));
      setEndTouched(false);
    } else {
      setDraftStart(isoFromDay(ranges[next.index].start));
      setDraftEnd(isoFromDay(ranges[next.index].end));
      setEndTouched(true);
    }
  };

  const changeDraftStart = (value: string) => {
    setDraftStart(value);
    if (!endTouched && ISO_DATE.test(value)) setDraftEnd(isoFromDay(dayNumber(value) + PLANNED_DAYS - 1));
  };

  const changeDraftEnd = (value: string) => {
    setDraftEnd(value);
    setEndTouched(true);
  };

  const cancelDraft = () => {
    setDraft(null);
    draftTriggerRef.current?.focus({ preventScroll: true });
  };

  const submitDraft = () => {
    if (draft === null || draftStartDay === null || draftEndDay === null || draftError) return;
    const range = { start: draftStartDay, end: draftEndDay };
    const span = `${longDate(range.start)} to ${longDate(range.end)}`;
    if (draft.mode === "create") {
      const index = ranges.length;
      saveRanges([...ranges.slice(0, -1), { start: newest.start, end: newestEndAfterCreate(range.start) }, range]);
      setDraft(null);
      setPagesBack(0);
      focusAfterCreate.current = index;
      setAnnouncement(`Sprint ${index + 1} created, ${span}.`);
    } else {
      saveRanges(ranges.map((r, i) => (i === draft.index ? range : r)));
      setDraft(null);
      setSelectedDay(null);
      draftTriggerRef.current?.focus({ preventScroll: true });
      setAnnouncement(`Sprint ${draft.index + 1} now runs ${span}.`);
    }
  };

  // Commit lands on today, so it is only offered where today is on screen: the
  // overview page holding the current sprint, or that sprint's own view.
  const currentOnScreen = currentIndex >= windowStart && currentIndex < windowEnd;
  const showCommitAction = selected === null ? currentOnScreen : isCurrentSprint;
  const showReset = Object.keys(extra).length > 0 || customRanges !== null;

  const enter = shouldReduceMotion ? { opacity: 0 } : { opacity: 0, y: 6 };

  const cellFill = (level: 0 | 1 | 2 | 3 | 4, upcoming: boolean, className: string) =>
    upcoming ? (
      <span className={`absolute inset-0 border border-dashed border-stone-300 dark:border-stone-700 ${className}`} />
    ) : (
      <>
        <span className={`absolute inset-0 block dark:hidden ${className}`} style={{ backgroundColor: ramp(level, false) ?? "rgb(226 232 240)" }} />
        <span className={`absolute inset-0 hidden dark:block ${className}`} style={{ backgroundColor: ramp(level, true) ?? "rgb(255 255 255 / 0.08)" }} />
      </>
    );

  return (
    <div
      onKeyDown={(event) => {
        if (event.key !== "Escape") return;
        if (draft !== null) cancelDraft();
        else if (selected !== null) closeDetail();
      }}
      className="w-full max-w-md rounded-2xl border border-stone-200 bg-white p-4 dark:border-stone-800 dark:bg-stone-900"
    >
      <p className="sr-only" role="status" aria-live="polite">
        {announcement}
      </p>

      <div className="flex flex-wrap items-start justify-between gap-3">
        {detail === null || selected === null ? (
          <div>
            <div className="flex items-center gap-1.5">
              <p className="text-sm font-semibold text-stone-800 dark:text-stone-100">Commit activity</p>
              {streak > 0 && (
                <motion.span
                  initial={shouldReduceMotion ? { opacity: 0 } : { opacity: 0, scale: 0.8 }}
                  animate={{ opacity: 1, scale: 1 }}
                  className="inline-flex items-center gap-0.5 rounded-full bg-orange-500/10 px-1.5 py-0.5 text-[11px] font-semibold text-orange-600 dark:text-orange-400"
                >
                  <FlameIcon />
                  {streak}
                </motion.span>
              )}
            </div>
            <p className="text-xs text-stone-500 dark:text-stone-500">
              {windowTotal} commits in sprints {windowStart + 1} to {windowEnd}
            </p>
            <p className="text-[11px] text-stone-500 dark:text-stone-500">
              {current
                ? `Sprint ${currentIndex + 1} began ${longDate(current.start)}, ${
                    current.overBy > 0
                      ? `${plural(current.overBy, "day")} past its end date`
                      : `day ${today - current.start + 1} of ${current.end - current.start + 1}`
                  }`
                : sprints[lastIndex].status === "planned"
                  ? `Between sprints. Sprint ${lastIndex + 1} starts ${longDate(sprints[lastIndex].start)}`
                  : "Between sprints"}
            </p>
          </div>
        ) : (
          <div>
            <div className="flex items-center gap-1.5">
              <button
                ref={backRef}
                type="button"
                onClick={closeDetail}
                className={`inline-flex items-center gap-1 rounded-full px-1.5 py-0.5 text-[11px] font-medium text-stone-500 transition-colors hover:bg-black/5 hover:text-stone-700 dark:text-stone-400 dark:hover:bg-white/10 dark:hover:text-stone-200 ${FOCUS}`}
              >
                <BackIcon />
                All sprints
              </button>
            </div>
            <div className="mt-1 flex items-center gap-1.5">
              <button
                type="button"
                onClick={() => openSprint(selected - 1)}
                disabled={selected === 0}
                aria-label={`Sprint ${selected}, the sprint before this one`}
                title={selected === 0 ? "No older sprint" : `Sprint ${selected}`}
                className={`inline-flex h-5 w-5 items-center justify-center rounded-full text-stone-500 transition-colors hover:bg-black/5 hover:text-stone-600 disabled:pointer-events-none disabled:opacity-50 dark:hover:bg-white/10 dark:hover:text-stone-300 ${FOCUS}`}
              >
                <OlderIcon />
              </button>
              <p className="text-sm font-semibold text-stone-800 dark:text-stone-100">Sprint {selected + 1}</p>
              <button
                type="button"
                onClick={() => openSprint(selected + 1)}
                disabled={selected === lastIndex}
                aria-label={`Sprint ${selected + 2}, the sprint after this one`}
                title={selected === lastIndex ? "No newer sprint" : `Sprint ${selected + 2}`}
                className={`inline-flex h-5 w-5 items-center justify-center rounded-full text-stone-500 transition-colors hover:bg-black/5 hover:text-stone-600 disabled:pointer-events-none disabled:opacity-50 dark:hover:bg-white/10 dark:hover:text-stone-300 ${FOCUS}`}
              >
                <NewerIcon />
              </button>
              {detail.status !== "done" && (
                <span className="rounded-full bg-stone-900/[0.06] px-1.5 py-0.5 text-[11px] font-medium uppercase tracking-[0.08em] text-stone-500 dark:bg-white/10 dark:text-stone-500">
                  {detail.status === "current" ? "In progress" : "Planned"}
                </span>
              )}
            </div>
            <div className="mt-1 flex flex-wrap items-center gap-x-2 gap-y-1">
              <p className="text-xs text-stone-600 dark:text-stone-400">
                {longDate(detail.start)} to {longDate(detail.end)}, {plural(detail.end - detail.start + 1, "day")}
                {detail.overBy > 0 && `, ${detail.overBy} past its end date`}
              </p>
              <button
                type="button"
                onClick={(event) => (draft?.mode === "edit" ? cancelDraft() : openDraft({ mode: "edit", index: selected }, event.currentTarget))}
                aria-expanded={draft?.mode === "edit"}
                className={`inline-flex items-center gap-1 rounded-full px-1.5 py-0.5 text-[11px] font-medium text-emerald-700 transition-colors hover:bg-emerald-500/10 dark:text-emerald-400 ${FOCUS}`}
              >
                <PencilIcon />
                Edit dates
              </button>
            </div>
            {selected > 0 && ranges[selected].start - ranges[selected - 1].end > 1 && (
              <p className="text-[11px] text-stone-500 dark:text-stone-500">
                Starts {plural(ranges[selected].start - ranges[selected - 1].end - 1, "day")} after Sprint {selected} ended
              </p>
            )}
            <p className="text-xs text-stone-500 dark:text-stone-500">
              {detail.status === "planned" ? (
                `Starts ${relativeDay(detail.start, today)}`
              ) : (
                <>
                  {detail.total} commits, {detail.activeDays} of {detail.elapsedDays} days active, busiest {detail.best}
                  {delta !== null && (
                    <span className={delta > 0 ? "text-green-600 dark:text-green-400" : undefined}>
                      {", "}
                      {delta > 0 ? "+" : ""}
                      {delta} vs S{selected}
                    </span>
                  )}
                </>
              )}
            </p>
          </div>
        )}

        <div className="flex items-center gap-1">
          {showReset && selected === null && (
            <button
              type="button"
              onClick={handleReset}
              aria-label="Reset sprints and commits to the sample history"
              title="Reset sprints and commits"
              className={`inline-flex h-7 w-7 items-center justify-center rounded-full text-stone-500 transition-colors hover:bg-black/5 hover:text-stone-600 dark:hover:bg-white/10 dark:hover:text-stone-300 ${FOCUS}`}
            >
              <ResetIcon />
            </button>
          )}
          {selected === null && (
            <button
