const cx = (...c: Array<string | false | null | undefined>) => c.filter(Boolean).join(" ");

/* ------------------------------------------------------------------ *
 * Data
 * ------------------------------------------------------------------ */

export interface SprintContributor {
  id: string;
  name: string;
  authored: number;
  merged: number;
  /** Reviews this person left on other people's PRs. */
  reviews: number;
  /** Median hours from opening a PR to its first review. */
  reviewHours: number;
  /** Median hours from opening a PR to merging it. */
  mergeHours: number;
}

/** One bucket of merged PRs: a change type or a size band. */
export interface SprintBucket {
  id: string;
  label: string;
  merged: number;
  /** Size bands only: counts towards the large-PR share. */
  large?: boolean;
}

export interface SprintDay {
  id: string;
  /** Short calendar label, e.g. "Mon 14". Rows are in calendar order. */
  label: string;
  opened: number;
  merged: number;
}

export interface SprintPrReportProps {
  /** e.g. "Sprint 38". */
  sprint: string;
  /** e.g. "Sep 14 to 25". */
  range: string;
  contributors: SprintContributor[];
  changeTypes: SprintBucket[];
  days: SprintDay[];
  sizes: SprintBucket[];
  /** Plot height in px for the vertical charts. Pies and horizontal bars scale from it. */
  chartHeight?: number;
  className?: string;
}

type DatasetKey = "people" | "types" | "days" | "sizes";
type ChartKind = "column" | "bar" | "stacked" | "line" | "area" | "pie" | "donut" | "burnup";

const DATASETS: { key: DatasetKey; label: string }[] = [
  { key: "people", label: "Contributors" },
  { key: "types", label: "Change types" },
  { key: "days", label: "Merged per day" },
  { key: "sizes", label: "PR size" },
];

const MEASURES = ["Authored vs merged", "Reviews vs authored", "Hours to review and merge"] as const;

const CHART_LABEL: Record<ChartKind, string> = {
  column: "Columns",
  bar: "Horizontal bars",
  stacked: "Stacked: merged + open",
  line: "Line",
  area: "Area",
  pie: "Pie",
  donut: "Donut",
  burnup: "Burn-up (cumulative)",
};

/**
 * Every dataset can be drawn every common way. Two are withheld where they would misstate the
 * data: a stack only where the parts add up to something (merged + still open = authored), and
 * a pie or donut only where the values are parts of a whole, which rules out summed hours.
 */
function chartKinds(dataset: DatasetKey, measure: number): ChartKind[] {
  const kinds: ChartKind[] = ["column", "bar"];
  if (dataset === "people" && measure === 0) kinds.push("stacked");
  kinds.push("line", "area");
  if (!(dataset === "people" && measure === 2)) kinds.push("pie", "donut");
  if (dataset === "days") kinds.push("burnup");
  return kinds;
}

/** One dataset, reduced to what every chart type needs. */
interface ChartModel {
  label: string;
  summary?: string;
  series: SeriesSpec[];
  /** In the table's sort order. */
  points: ChartPoint[];
  /** Calendar order, for time series that must not follow the sort. */
  timeline?: ChartPoint[];
  stack?: { series: SeriesSpec[]; points: ChartPoint[] };
  /** A single quantity split into parts, for pie and donut. */
  share?: { slices: { id: string; label: string; value: number }[]; caption: string };
  format?: (v: number) => string;
  unit?: string;
}

const maxOf = (points: ChartPoint[]) =>
  Math.max(0, ...points.flatMap((p) => Object.values(p.values).map((v) => v ?? 0)));

const VIEWS = ["Table", "Graph"];

/* ------------------------------------------------------------------ *
 * Maths
 * ------------------------------------------------------------------ */

function median(values: number[]): number {
  if (values.length === 0) return 0;
  const s = [...values].sort((a, b) => a - b);
  const mid = s.length >> 1;
  return s.length % 2 ? s[mid] : (s[mid - 1] + s[mid]) / 2;
}

const sum = (values: number[]) => values.reduce((a, b) => a + b, 0);
const pct = (v: number) => `${Math.round(v * 100)}%`;
const hours = (v: number) => `${v.toFixed(1)}h`;
/**
 * A value axis for whole counts. The frame picks whichever step lands nearest its tick count, and
 * on a 0 to 15 axis that is 2.5, which prints as 3, 5, 8, 13. Pinning the domain to a multiple of
 * a 1-2-5 step and asking for exactly that many ticks makes the step an integer.
 */
function countAxis(max: number, format?: (v: number) => string): AxisSpec {
  const want = Math.max(1, max) / 5;
  const mag = 10 ** Math.floor(Math.log10(want));
  const step = Math.max(1, [1, 2, 5, 10].map((m) => m * mag).find((v) => v >= want) ?? 10 * mag);
  const top = Math.max(step, Math.ceil(max / step) * step);
  return { domain: [0, top], ticks: Math.round(top / step), zero: true, format };
}

/** Rows whose id is checked, in their original order. */
function checked<T extends { id: string }>(rows: T[], ids: string[]): T[] {
  const on = new Set(ids);
  return rows.filter((r) => on.has(r.id));
}

const rateOf = (c: SprintContributor) => (c.authored > 0 ? c.merged / c.authored : 0);

/** The same ordering DataTable applies, so the chart reads rows in the order the table shows them. */
function applySort<T>(rows: T[], columns: DataColumn<T>[], sort: SortState): T[] {
  if (!sort) return rows;
  const col = columns.find((c) => c.key === sort.key);
  if (!col) return rows;
  const acc = col.sortAccessor ?? ((r: T) => (r as Record<string, unknown>)[sort.key] as string | number);
  return [...rows].sort((a, b) => {
    const av = acc(a);
    const bv = acc(b);
    const r = typeof av === "number" && typeof bv === "number" ? av - bv : String(av).localeCompare(String(bv));
    return sort.dir === "asc" ? r : -r;
  });
}

