    width: 116,
    sortAccessor: rateOf,
    render: (r) => pct(rateOf(r)),
  },
  {
    key: "open",
    header: "Open",
    align: "right",
    sortable: true,
    width: 88,
    sortAccessor: (r) => r.authored - r.merged,
    render: (r) => String(r.authored - r.merged),
  },
  { key: "reviews", header: "Reviews", align: "right", sortable: true, width: 100 },
  {
    key: "reviewHours",
    header: "1st review",
    align: "right",
    sortable: true,
    width: 112,
    render: (r) => hours(r.reviewHours),
  },
  {
    key: "mergeHours",
    header: "To merge",
    align: "right",
    sortable: true,
    width: 104,
    render: (r) => hours(r.mergeHours),
  },
];

/** Share is of the rows still checked, so it rebalances when one is dropped. */
function bucketColumns(head: string, total: number): DataColumn<SprintBucket>[] {
  return [
    { key: "label", header: head, sortable: true },
    { key: "merged", header: "Merged", align: "right", sortable: true, width: 120, bar: (r) => r.merged },
    {
      key: "share",
      header: "Share",
      align: "right",
      sortable: true,
      width: 104,
      sortAccessor: (r) => r.merged,
      render: (r) => (total > 0 ? pct(r.merged / total) : "0%"),
    },
  ];
}

function dayColumns(days: SprintDay[]): DataColumn<SprintDay>[] {
  const running = new Map<string, number>();
  let acc = 0;
  for (const d of days) {
    acc += d.merged;
    running.set(d.id, acc);
  }
  return [
    { key: "label", header: "Day", sortable: true, sortAccessor: (r) => days.indexOf(r) },
    { key: "opened", header: "Opened", align: "right", sortable: true, width: 104 },
    { key: "merged", header: "Merged", align: "right", sortable: true, width: 120, bar: (r) => r.merged },
    {
      key: "running",
      header: "Running total",
      align: "right",
      width: 132,
      render: (r) => String(running.get(r.id) ?? 0),
    },
  ];
}

