const PRIORITIES = ["No priority", "Low", "Medium", "High", "Urgent"] as const;

/** Where the "done" chime and the sprint progress read from. */
const DONE_ID = "done";

/**
 * A fixed "today" keeps the demo deterministic: every due-date chip renders
 * the same on the server and in the browser. In a real app this is the
 * current date.
 */
const TODAY = "2026-09-29";
const SPRINT_START = "2026-09-22";
const SPRINT_END = "2026-10-05";
const MONTHS = ["Jan", "Feb", "Mar", "Apr", "May", "Jun", "Jul", "Aug", "Sep", "Oct", "Nov", "Dec"];

function dayNumber(iso: string) {
  const [y, m, d] = iso.split("-").map(Number);
  return Math.round(Date.UTC(y, m - 1, d) / 86_400_000);
}

function shortDate(iso: string) {
  const [, m, d] = iso.split("-").map(Number);
  return `${MONTHS[m - 1]} ${d}`;
}

function dueState(iso: string | null, columnId: string): "none" | "overdue" | "soon" | "later" {
  if (!iso || columnId === DONE_ID) return "none";
  const diff = dayNumber(iso) - dayNumber(TODAY);
  if (diff < 0) return "overdue";
  if (diff <= 2) return "soon";
  return "later";
}

