/* ------------------------------------------------------------------------ */
/* Sound                                                                     */
/*                                                                           */
/* Synthesised with Web Audio, so there are no files to ship. Everything    */
/* runs through one master gain at 0.3: a board is a tool people sit in all  */
/* day, and the sounds are there to confirm, not to announce.               */
/* ------------------------------------------------------------------------ */

const MASTER_VOLUME = 0.3;

class Sfx {
  enabled = true;
  private ctx: AudioContext | null = null;
  private out: GainNode | null = null;

  private ac() {
    if (!this.enabled || typeof window === "undefined") return null;
    if (!this.ctx) {
      const Ctor = window.AudioContext ?? (window as unknown as { webkitAudioContext?: typeof AudioContext }).webkitAudioContext;
      if (!Ctor) return null;
      this.ctx = new Ctor();
      this.out = this.ctx.createGain();
      this.out.gain.value = MASTER_VOLUME;
      this.out.connect(this.ctx.destination);
    }
    if (this.ctx.state === "suspended") void this.ctx.resume();
    return this.ctx;
  }

  /** A dry click: picking a card up. */
  tick(vol = 0.12, freq = 1400) {
    const a = this.ac();
    if (!a || !this.out) return;
    const o = a.createOscillator();
    const g = a.createGain();
    const t = a.currentTime;
    o.type = "triangle";
    o.frequency.setValueAtTime(freq, t);
    o.frequency.exponentialRampToValueAtTime(freq * 0.6, t + 0.04);
    g.gain.setValueAtTime(vol, t);
    g.gain.exponentialRampToValueAtTime(0.001, t + 0.06);
    o.connect(g).connect(this.out);
    o.start(t);
    o.stop(t + 0.07);
  }

  /** A soft low tap: a card settling into place. */
  thud(vol = 0.22) {
    const a = this.ac();
    if (!a || !this.out) return;
    const o = a.createOscillator();
    const g = a.createGain();
    const t = a.currentTime;
    o.type = "sine";
    o.frequency.setValueAtTime(170, t);
    o.frequency.exponentialRampToValueAtTime(64, t + 0.09);
    g.gain.setValueAtTime(vol, t);
    g.gain.exponentialRampToValueAtTime(0.001, t + 0.12);
    o.connect(g).connect(this.out);
    o.start(t);
    o.stop(t + 0.13);
  }

  /** Filtered noise, the edge of a card brushing another. */
  flick(vol = 0.14, freq = 2600) {
    const a = this.ac();
    if (!a || !this.out) return;
    const n = Math.floor(a.sampleRate * 0.05);
    const buf = a.createBuffer(1, n, a.sampleRate);
    const d = buf.getChannelData(0);
    for (let i = 0; i < n; i++) d[i] = (Math.random() * 2 - 1) * Math.pow(1 - i / n, 3);
    const s = a.createBufferSource();
    const f = a.createBiquadFilter();
    const g = a.createGain();
    s.buffer = buf;
    f.type = "bandpass";
    f.frequency.value = freq * (0.85 + Math.random() * 0.3);
    f.Q.value = 0.9;
    g.gain.value = vol;
    s.connect(f).connect(g).connect(this.out);
    s.start();
  }

  private notes(freqs: number[], gap: number, vol: number, tail: number) {
    const a = this.ac();
    if (!a || !this.out) return;
    freqs.forEach((f, i) => {
      const o = a.createOscillator();
      const g = a.createGain();
      const t = a.currentTime + i * gap;
      o.type = "sine";
      o.frequency.value = f;
      g.gain.setValueAtTime(0, t);
      g.gain.linearRampToValueAtTime(vol, t + 0.01);
      g.gain.exponentialRampToValueAtTime(0.001, t + tail);
      o.connect(g).connect(this.out!);
      o.start(t);
      o.stop(t + tail + 0.05);
    });
  }

  /** Two rising notes: something new on the board. */
  pop() {
    this.notes([660, 990], 0.06, 0.08, 0.18);
  }

  /** A three-note major arpeggio: a card reached Done, or a deal finished. */
  chime() {
    this.notes([784, 1047, 1319], 0.09, 0.1, 0.5);
  }
}

