/** A column's hue tinted into the lane, derived in CSS so any pick works. */
function laneVars(color: string): CSSProperties {
  return {
    "--col": color,
    "--col-wash": `color-mix(in oklab, ${color} 9%, transparent)`,
    "--col-wash-dark": `color-mix(in oklab, ${color} 12%, transparent)`,
    "--col-drop": `color-mix(in oklab, ${color} 16%, transparent)`,
    "--col-line": `color-mix(in oklab, ${color} 55%, transparent)`,
  } as CSSProperties;
}

function PriorityGlyph({ priority, className }: { priority: Priority; className?: string }) {
  const label = PRIORITIES[priority];
  if (priority === 4) {
    return (
      <svg
        viewBox="0 0 14 14"
        className={cn("h-3.5 w-3.5 text-amber-700 dark:text-amber-400", className)}
        role="img"
        aria-label={label}
      >
        <rect x="1" y="1" width="12" height="12" rx="3" fill="currentColor" />
        <rect x="6.25" y="3.5" width="1.5" height="4.5" rx="0.75" className="fill-white dark:fill-stone-900" />
        <rect x="6.25" y="9.25" width="1.5" height="1.5" rx="0.75" className="fill-white dark:fill-stone-900" />
      </svg>
    );
  }
  return (
    <svg viewBox="0 0 14 14" className={cn("h-3.5 w-3.5", className)} role="img" aria-label={label}>
