function Initials({ person, size = "sm" }: { person: Person; size?: "xs" | "sm" }) {
  return (
    <span
      title={person.name}
      className={cn(
        "inline-flex shrink-0 items-center justify-center overflow-hidden rounded-full font-semibold text-white ring-2 ring-white dark:ring-stone-900",
        size === "xs" ? "h-6 w-6 text-[11px]" : "h-7 w-7 text-[11px]",
        person.color
      )}
