function ColumnMenu({
  column,
  count,
  onRename,
  onDelete,
  canDelete,
}: {
  column: Column;
  count: number;
  onRename: () => void;
  onDelete: () => void;
  canDelete: boolean;
}) {
  const reduce = useReducedMotion();
  const [open, setOpen] = useState(false);
  const ref = useRef<HTMLDivElement>(null);
  const close = useCallback(() => setOpen(false), []);
  useDismiss(open, ref, close);
  const item =
    "flex w-full items-center gap-2 rounded-md px-2 py-1.5 text-left text-xs text-stone-700 transition-colors duration-150 hover:bg-stone-100 disabled:pointer-events-none disabled:opacity-50 dark:text-stone-200 dark:hover:bg-stone-700 " +
    FOCUS;

  return (
    <div ref={ref} className="relative">
      <button
        type="button"
        aria-label={`${column.name} options`}
        aria-haspopup="menu"
        aria-expanded={open}
        onClick={() => setOpen((o) => !o)}
        className={cn(ICON_BTN, "h-7 w-7")}
      >
        <Ellipsis aria-hidden className="h-4 w-4" />
      </button>
      <AnimatePresence>
        {open && (
          <motion.div
            role="menu"
            initial={reduce ? { opacity: 0 } : { opacity: 0, scale: 0.97, y: -2 }}
            animate={{ opacity: 1, scale: 1, y: 0 }}
            exit={{ opacity: 0, transition: { duration: 0.1 } }}
            transition={{ duration: 0.16, ease: EASE_OUT }}
            style={{ transformOrigin: "top right" }}
            className={cn(FLOATING, "absolute right-0 top-8 z-30 w-52 p-1")}
          >
            <button
              type="button"
              role="menuitem"
              className={item}
              onClick={() => {
                setOpen(false);
                onRename();
              }}
            >
              <Pencil aria-hidden className="h-3.5 w-3.5" /> Rename
            </button>
            <button
              type="button"
              role="menuitem"
              disabled={!canDelete}
              className={cn(item, "text-red-700 hover:bg-red-50 dark:text-red-400 dark:hover:bg-red-950/40")}
              onClick={() => {
                setOpen(false);
                onDelete();
              }}
            >
              <Trash2 aria-hidden className="h-3.5 w-3.5" />
              {count > 0 ? `Delete, keeping ${count} ${count === 1 ? "card" : "cards"}` : "Delete column"}
            </button>
          </motion.div>
        )}
      </AnimatePresence>
    </div>
  );
}

function QuickAdd({ onAdd, onClose }: { onAdd: (title: string) => void; onClose: () => void }) {
  const [text, setText] = useState("");
  const ref = useRef<HTMLTextAreaElement>(null);
  useEffect(() => ref.current?.focus(), []);
  const submit = () => {
    const t = text.trim();
    if (!t) return;
    onAdd(t);
    setText("");
  };
  return (
    <div className="rounded-xl border border-stone-300 bg-white p-2 dark:border-stone-700 dark:bg-stone-900">
      <textarea
        ref={ref}
        rows={2}
        value={text}
        onChange={(e) => setText(e.target.value)}
        onKeyDown={(e) => {
          if (e.key === "Enter" && !e.shiftKey) {
            e.preventDefault();
            submit();
          } else if (e.key === "Escape") {
            e.stopPropagation();
            onClose();
          }
        }}
        aria-label="New card title"
        placeholder="What needs doing?"
        className="block w-full resize-none bg-transparent px-1 text-sm leading-5 text-stone-900 outline-none placeholder:text-stone-400 dark:text-stone-100 dark:placeholder:text-stone-600"
      />
      <div className="mt-2 flex items-center gap-2">
        <button type="button" onClick={submit} disabled={!text.trim()} className={cn(PRIMARY, "h-8 px-3 text-xs")}>
          Add card
        </button>
        <button type="button" onClick={onClose} className={cn(ICON_BTN, "h-8 w-8")} aria-label="Close">
          <X aria-hidden className="h-4 w-4" />
        </button>
        <span className="ml-auto text-[11px] text-stone-500">Enter to add</span>
      </div>
    </div>
  );
}

