}) {
  const [name, setName] = useState("");
  const [color, setColor] = useState("#0d9488");
  const ref = useRef<HTMLInputElement>(null);
  useEffect(() => ref.current?.focus(), []);
  return (
    <form
      className={cn(
        "flex flex-col gap-2",
        !compact && "rounded-2xl border border-stone-200 bg-white p-3 dark:border-stone-800 dark:bg-stone-900"
      )}
      onSubmit={(e) => {
        e.preventDefault();
        if (name.trim()) onCreate(name.trim(), color);
      }}
    >
      {!compact && <span className={EYEBROW}>New column</span>}
      <div className="flex items-center gap-2">
        <ColorPicker
          value={color}
          onChange={setColor}
          label="Column colour"
          swatches={swatches}
          triggerClassName={cn("h-8 w-8 shrink-0 rounded-md ring-1 ring-inset ring-black/10 dark:ring-white/15", FOCUS)}
        />
        <input
          ref={ref}
          value={name}
          onChange={(e) => setName(e.target.value)}
          onKeyDown={(e) => {
            if (e.key === "Escape") {
              e.stopPropagation();
              onCancel();
            }
          }}
          maxLength={24}
          placeholder="Column name"
          aria-label="Column name"
          className={cn(INPUT, "h-8 min-w-0 flex-1")}
        />
      </div>
      <div className="flex gap-2">
        <button type="submit" disabled={!name.trim()} className={cn(PRIMARY, "h-8 px-3 text-xs")}>
          Add column
        </button>
        <button type="button" onClick={onCancel} className={cn(GHOST, "h-8 px-3 text-xs")}>
          Cancel
        </button>
      </div>
    </form>
  );
}

/* ------------------------------------------------------------------------ */
/* Label menu (toolbar and editor share it)                                  */
/* ------------------------------------------------------------------------ */

function LabelMenu({
  labels,
  selected,
  onToggle,
  onCreate,
  onRecolor,
  swatches,
  trigger,
  align = "start",
}: {
  labels: Label[];
  selected: Set<string>;
  onToggle: (id: string) => void;
  onCreate: (name: string, color: string) => void;
  onRecolor: (id: string, hex: string) => void;
  swatches: string[];
  trigger: (props: { open: boolean; toggle: () => void }) => ReactNode;
  align?: "start" | "end";
}) {
  const reduce = useReducedMotion();
  const [open, setOpen] = useState(false);
  const [name, setName] = useState("");
  const [color, setColor] = useState("#d97706");
  const ref = useRef<HTMLDivElement>(null);
  const close = useCallback(() => setOpen(false), []);
  useDismiss(open, ref, close);

  const create = () => {
    const n = name.trim();
    if (!n) return;
    onCreate(n, color);
    setName("");
  };

  return (
    <div ref={ref} className="relative">
      {trigger({ open, toggle: () => setOpen((o) => !o) })}
      <AnimatePresence>
        {open && (
          <motion.div
            role="dialog"
            aria-label="Labels"
            initial={reduce ? { opacity: 0 } : { opacity: 0, scale: 0.97, y: -2 }}
            animate={{ opacity: 1, scale: 1, y: 0 }}
            exit={{ opacity: 0, transition: { duration: 0.1 } }}
            transition={{ duration: 0.18, ease: EASE_OUT }}
            style={{ transformOrigin: align === "end" ? "top right" : "top left" }}
            className={cn(FLOATING, "absolute top-full z-30 mt-1.5 w-72 p-2", align === "end" ? "right-0" : "left-0")}
          >
            <ul className="flex max-h-48 flex-col gap-0.5 overflow-y-auto overscroll-contain" data-lenis-prevent>
              {labels.map((l) => {
                const on = selected.has(l.id);
                return (
                  <li key={l.id} className="flex items-center gap-1">
                    <button
                      type="button"
                      role="menuitemcheckbox"
                      aria-checked={on}
                      onClick={() => onToggle(l.id)}
                      className={cn(
                        "flex min-w-0 flex-1 items-center gap-2 rounded-md px-2 py-1.5 text-left transition-colors duration-150 hover:bg-stone-100 dark:hover:bg-stone-700",
                        FOCUS
                      )}
                    >
                      <span
                        aria-hidden
                        className={cn(
                          "flex h-4 w-4 shrink-0 items-center justify-center rounded border",
                          on ? "border-emerald-700 bg-emerald-700 text-white" : "border-stone-300 dark:border-stone-600"
                        )}
                      >
                        {on && <Check className="h-3 w-3" strokeWidth={3} />}
                      </span>
                      <LabelChip color={l.color} size="sm">
                        {l.name}
                      </LabelChip>
                    </button>
                    <ColorPicker
                      value={l.color}
                      onChange={(hex) => onRecolor(l.id, hex)}
                      label={`${l.name} label colour`}
                      swatches={swatches}
                      triggerClassName={cn(
                        "mr-1 h-5 w-5 shrink-0 rounded-full ring-1 ring-inset ring-black/15 transition-shadow duration-150 hover:ring-2 dark:ring-white/25",
                        FOCUS
                      )}
                    />
                  </li>
                );
              })}
            </ul>
            <form
              className="mt-2 flex items-center gap-1.5 border-t border-stone-200 pt-2 dark:border-stone-700"
              onSubmit={(e) => {
                e.preventDefault();
                create();
              }}
            >
              <ColorPicker
                value={color}
                onChange={setColor}
                label="New label colour"
                swatches={swatches}
                triggerClassName={cn("h-8 w-8 shrink-0 rounded-md ring-1 ring-inset ring-black/10 dark:ring-white/15", FOCUS)}
              />
              <input
                value={name}
                onChange={(e) => setName(e.target.value)}
                maxLength={20}
                placeholder="New label"
                aria-label="New label name"
                className={cn(INPUT, "h-8 min-w-0 flex-1 px-2 text-xs")}
              />
              <button type="submit" disabled={!name.trim()} className={cn(ICON_BTN, "h-8 w-8")} aria-label="Create label">
                <Plus aria-hidden className="h-4 w-4" />
              </button>
            </form>
          </motion.div>
        )}
      </AnimatePresence>
    </div>
  );
}

/* ------------------------------------------------------------------------ */
/* Card fields (the sheet and the create dialog render the same form)       */
