/** Keeps Tab inside `ref`, and hands focus back to whatever opened it. */
function useFocusTrap(ref: React.RefObject<HTMLElement | null>, initial?: React.RefObject<HTMLElement | null>) {
  useEffect(() => {
    const opener = document.activeElement as HTMLElement | null;
    const el = ref.current;
    (initial?.current ?? el)?.focus({ preventScroll: true });
    const onKey = (e: KeyboardEvent) => {
      if (e.key !== "Tab" || !el) return;
      const f = Array.from(
        el.querySelectorAll<HTMLElement>('button:not([disabled]), input, textarea, select, [tabindex]:not([tabindex="-1"])')
      ).filter((n) => n.offsetParent !== null);
      if (!f.length) return;
      const first = f[0];
      const last = f[f.length - 1];
      if (e.shiftKey && document.activeElement === first) {
        e.preventDefault();
        last.focus();
      } else if (!e.shiftKey && document.activeElement === last) {
        e.preventDefault();
        first.focus();
      }
    };
    el?.addEventListener("keydown", onKey);
    return () => {
      el?.removeEventListener("keydown", onKey);
      opener?.focus?.({ preventScroll: true });
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);
}

/** Escape closes, unless a picker or listbox inside is the thing that is open. */
function useEscape(onClose: () => void) {
  useEffect(() => {
    const onKey = (e: KeyboardEvent) => {
      if (e.key !== "Escape") return;
      if (document.querySelector("[data-color-picker]")) return;
      if ((document.activeElement as HTMLElement | null)?.getAttribute("aria-expanded") === "true") return;
      onClose();
    };
    window.addEventListener("keydown", onKey);
    return () => window.removeEventListener("keydown", onKey);
  }, [onClose]);
}

function CardSheet({
  card,
  board,
  bc,
  swatches,
  patch,
  createLabel,
  createColumn,
  onDelete,
  onClose,
  recolor,
  onOpenCard,
  onAddChild,
  onLink,
  onUnlink,
}: Omit<CardFieldsProps, "titleRef"> & {
  bc: BoardCtx;
  onDelete: () => void;
  onClose: () => void;
  onOpenCard: (id: string) => void;
  onAddChild: (title: string) => void;
  onLink: (childId: string) => void;
  onUnlink: (childId: string) => void;
}) {
  const reduce = useReducedMotion();
  const ref = useRef<HTMLDivElement>(null);
  const titleId = useId();
  useFocusTrap(ref);
  useEscape(onClose);
  const col = board.columns.find((c) => c.id === card.columnId);
  const parent = card.parentId ? board.cards.find((c) => c.id === card.parentId) : undefined;

  return (
    <motion.aside
      ref={ref}
      role="dialog"
      aria-modal="true"
      aria-labelledby={titleId}
      tabIndex={-1}
      initial={reduce ? { opacity: 0 } : { opacity: 0, x: 32 }}
      animate={{ opacity: 1, x: 0 }}
      exit={reduce ? { opacity: 0 } : { opacity: 0, x: 16, transition: { duration: 0.16, ease: EASE_OUT } }}
      transition={{ duration: 0.28, ease: EASE_DRAWER }}
      className="pointer-events-auto absolute inset-y-0 right-0 z-40 flex w-[440px] max-w-full flex-col border-l border-stone-200 bg-white outline-none dark:border-stone-800 dark:bg-stone-900"
    >
      <header className="flex shrink-0 items-center gap-2 border-b border-stone-200 px-5 py-3 dark:border-stone-800">
        <span
          aria-hidden
          className="h-2 w-2 rounded-full ring-1 ring-inset ring-black/15 dark:ring-white/20"
          style={{ background: col?.color }}
        />
        <h2 id={titleId} className="font-[family-name:var(--font-deck-mono)] text-xs text-stone-600 dark:text-stone-400">
          {card.key}
          <span className="sr-only">, {card.title}</span>
        </h2>
        <span className="text-xs text-stone-500">in {col?.name}</span>
        <span className="flex-1" />
        {card.source && (
          <a
            href={card.source.url}
            target="_blank"
            rel="noreferrer"
            className={ICON_BTN}
            aria-label={`Open ${card.source.ref} on GitHub`}
            title="Open on GitHub"
          >
            <ExternalLink aria-hidden className="h-4 w-4" />
          </a>
        )}
        <button
          type="button"
          onClick={onDelete}
          className={cn(ICON_BTN, "hover:text-red-700 dark:hover:text-red-400")}
          aria-label="Delete card"
        >
          <Trash2 aria-hidden className="h-4 w-4" />
        </button>
        <button type="button" onClick={onClose} className={ICON_BTN} aria-label="Close">
          <X aria-hidden className="h-4 w-4" />
        </button>
      </header>

      <div className="min-h-0 flex-1 overflow-y-auto overscroll-contain px-5 py-5" data-lenis-prevent>
        {parent && (
          <button
            type="button"
            onClick={() => onOpenCard(parent.id)}
            className={cn(
              "mb-3 inline-flex max-w-full items-center gap-1.5 rounded-full border border-stone-300 px-2.5 py-1 text-xs text-stone-600 transition-colors duration-150 hover:border-stone-400 hover:text-stone-900 dark:border-stone-700 dark:text-stone-400 dark:hover:border-stone-500 dark:hover:text-stone-100",
              FOCUS
            )}
          >
            <CornerDownRight aria-hidden className="h-3.5 w-3.5 shrink-0" />
            <span className="shrink-0">Sub-issue of</span>
            <span className="shrink-0 font-[family-name:var(--font-deck-mono)]">{parent.key}</span>
            <span className="truncate">{parent.title}</span>
          </button>
        )}
        <CardFields
          card={card}
          board={board}
          swatches={swatches}
          patch={patch}
          createLabel={createLabel}
          createColumn={createColumn}
          recolor={recolor}
        />

        <div className="mt-6">
          <SubIssues card={card} bc={bc} onOpenCard={onOpenCard} onAddChild={onAddChild} onLink={onLink} onUnlink={onUnlink} />
        </div>

        <div className="mt-8 flex flex-col gap-3">
          <span className={cn(EYEBROW, "inline-flex items-center gap-1.5")}>
            <History aria-hidden className="h-3.5 w-3.5" /> Activity
          </span>
          <ol className="relative flex flex-col gap-3 border-l border-stone-200 pl-4 dark:border-stone-800">
            {[...card.activity].reverse().map((a) => (
              <li key={a.id} className="relative text-xs text-stone-600 dark:text-stone-400">
                <span
                  aria-hidden
                  className="absolute -left-[21px] top-1 h-2 w-2 rounded-full border-2 border-white bg-stone-400 dark:border-stone-900 dark:bg-stone-600"
                />
                {a.text}
                <span className="ml-1.5 text-stone-500">{a.at}</span>
              </li>
            ))}
          </ol>
        </div>
      </div>
    </motion.aside>
  );
}

function CreateDialog({
  draft,
  setDraft,
  board,
  swatches,
  createLabel,
  createColumn,
  recolor,
  onCreate,
  onClose,
}: {
  recolor: Recolor;
  draft: Card;
  setDraft: (fn: (d: Card) => Card) => void;
  board: Board;
  swatches: string[];
  createLabel: (name: string, color: string) => string;
  createColumn: (name: string, color: string) => string;
  onCreate: () => void;
  onClose: () => void;
}) {
  const reduce = useReducedMotion();
  const ref = useRef<HTMLDivElement>(null);
  const titleRef = useRef<HTMLTextAreaElement>(null);
  const headingId = useId();
  useFocusTrap(ref, titleRef);
  useEscape(onClose);
  const ok = draft.title.trim().length > 0;

  return (
    <div
      className="pointer-events-auto absolute inset-0 z-40 flex items-start justify-center overflow-y-auto overscroll-contain p-4 pt-12 sm:pt-16"
      data-lenis-prevent
    >
      <motion.div
        ref={ref}
        role="dialog"
        aria-modal="true"
        aria-labelledby={headingId}
        initial={reduce ? { opacity: 0 } : { opacity: 0, scale: 0.96, y: 8 }}
        animate={{ opacity: 1, scale: 1, y: 0 }}
        exit={reduce ? { opacity: 0 } : { opacity: 0, scale: 0.98, transition: { duration: 0.14, ease: EASE_OUT } }}
        transition={{ duration: 0.24, ease: EASE_OUT }}
        onKeyDown={(e) => {
          if (e.key === "Enter" && (e.metaKey || e.ctrlKey) && ok) onCreate();
        }}
        className="relative w-full max-w-lg rounded-2xl border border-stone-200 bg-white ring-1 ring-stone-900/5 shadow-[0_1px_2px_-1px_rgba(0,0,0,0.06),0_24px_48px_-16px_rgba(28,25,23,0.25)] dark:border-stone-800 dark:bg-stone-900 dark:ring-white/10 dark:shadow-none"
      >
        <div className="flex items-center gap-2 border-b border-stone-200 px-5 py-3 dark:border-stone-800">
          <h2 id={headingId} className="text-sm font-medium text-stone-900 dark:text-stone-100">
            New card
          </h2>
          <span className="font-[family-name:var(--font-deck-mono)] text-xs text-stone-500">{draft.key}</span>
          <span className="flex-1" />
          <button type="button" onClick={onClose} className={ICON_BTN} aria-label="Close">
            <X aria-hidden className="h-4 w-4" />
          </button>
        </div>
        <div className="px-5 py-5">
          <CardFields
            card={draft}
            board={board}
            swatches={swatches}
            patch={(p) => setDraft((d) => ({ ...d, ...p }))}
            createLabel={createLabel}
            createColumn={createColumn}
            recolor={recolor}
            titleRef={titleRef}
          />
        </div>
        <div className="flex items-center gap-2 border-t border-stone-200 px-5 py-3 dark:border-stone-800">
          <span className="hidden text-xs text-stone-500 sm:inline">
            <kbd className="font-[family-name:var(--font-deck-mono)]">Ctrl</kbd> or{" "}
            <kbd className="font-[family-name:var(--font-deck-mono)]">Cmd</kbd> + Enter to create
          </span>
          <span className="flex-1" />
          <button type="button" onClick={onClose} className={GHOST}>
            Cancel
          </button>
          <button type="button" onClick={onCreate} disabled={!ok} className={PRIMARY}>
            Create card
          </button>
        </div>
      </motion.div>
    </div>
  );
}

/* ------------------------------------------------------------------------ */
/* GitHub import                                                             */
/*                                                                           */
/* Reads a repo's issues from GitHub's REST API in the browser. Public repos */
/* need nothing; a token (kept in memory, never stored) opens private ones   */
/* and lifts the signed-out limit of 60 requests an hour.                    */
/* ------------------------------------------------------------------------ */

interface GhIssue {
  id: number;
  number: number;
  title: string;
  body: string | null;
  state: "open" | "closed";
  html_url: string;
  labels: Array<string | { name?: string; color?: string }>;
  assignee: { login: string; avatar_url: string } | null;
  milestone: { due_on: string | null } | null;
  created_at: string;
  closed_at: string | null;
  sub_issues_summary?: { total: number; completed: number };
  pull_request?: unknown;
}

function GithubMark({ className }: { className?: string }) {
  return (
    <svg viewBox="0 0 16 16" aria-hidden className={className} fill="currentColor">
      <path d="M8 0c4.42 0 8 3.58 8 8a8.013 8.013 0 0 1-5.45 7.59c-.4.08-.55-.17-.55-.38 0-.27.01-1.13.01-2.2 0-.75-.25-1.23-.54-1.48 1.78-.2 3.65-.88 3.65-3.95 0-.88-.31-1.59-.82-2.15.08-.2.36-1.02-.08-2.12 0 0-.67-.22-2.2.82-.64-.18-1.32-.27-2-.27-.68 0-1.36.09-2 .27-1.53-1.03-2.2-.82-2.2-.82-.44 1.1-.16 1.92-.08 2.12-.51.56-.82 1.28-.82 2.15 0 3.06 1.86 3.75 3.64 3.95-.23.2-.44.55-.51 1.07-.46.21-1.61.55-2.33-.66-.15-.24-.6-.83-1.23-.82-.67.01-.27.38.01.53.34.19.73.9.82 1.13.16.45.68 1.31 2.69.94 0 .67.01 1.3.01 1.49 0 .21-.15.45-.55.38A7.995 7.995 0 0 1 0 8c0-4.42 3.58-8 8-8Z" />
    </svg>
  );
}

/** "owner/repo", or any github.com URL inside the repo. */
function parseRepo(input: string): string | null {
  const m = input.trim().match(/^(?:https?:\/\/)?(?:www\.)?(?:github\.com\/)?([\w.-]+)\/([\w.-]+?)(?:\.git)?(?:[/?#].*)?$/i);
  return m ? `${m[1]}/${m[2]}` : null;
}

const TASK_RE = /^\s*[-*]\s+\[( |x|X)\]\s+(.+)$/gm;

function priorityFromLabels(names: string[]): Priority {
  const t = names.join(" ").toLowerCase();
  if (/\b(urgent|critical|blocker|p0)\b/.test(t)) return 4;
  if (/\b(high|p1)\b/.test(t)) return 3;
  if (/\b(medium|p2)\b/.test(t)) return 2;
  if (/\b(low|p3)\b/.test(t)) return 1;
  return 0;
}

/** Imported assignees take the next rung of the same ladder the seed team uses. */
const IMPORT_LADDER = ["bg-emerald-900", "bg-amber-900", "bg-stone-700", "bg-emerald-700", "bg-amber-700"];

/** A task-list line that points at another issue: "- [ ] #123" or "- [x] Fix it (#123)". */
const ISSUE_REF_RE = /(?:^|[\s(])#(\d+)\b/;

/**
 * Issues become cards; a task list inside an issue becomes sub-issue cards
 * under it, and a task line that names another issue links that issue's card
 * as a sub-issue instead of duplicating it. GitHub's own sub-issue count is
 * kept for a parent whose children were not imported.
 */
function importIssues(b: Board, repo: string, issues: GhIssue[], openCol: string): { board: Board; added: number } {
  const labels = [...b.labels];
  const people = [...b.people];
  let cards = [...b.cards];
  let seq = b.seq;
  let added = 0;
  const doneCol = b.columns.some((c) => c.id === DONE_ID) ? DONE_ID : openCol;
  const links: { parentRef: string; childRef: string }[] = [];

  for (const issue of issues) {
    const ref = `${repo}#${issue.number}`;
    if (cards.some((c) => c.source?.ref === ref)) continue;
    seq += 1;
    const id = `n${seq}`;

    const ghLabels = issue.labels
      .map((l) => (typeof l === "string" ? { name: l, color: undefined } : l))
      .filter((l): l is { name: string; color?: string } => !!l.name);
    const labelIds = ghLabels.map((l) => {
      const found = labels.find((x) => x.name.toLowerCase() === l.name.toLowerCase());
      if (found) return found.id;
      const lid = `gh-${seq}-${labels.length}`;
      labels.push({ id: lid, name: l.name, color: l.color ? `#${l.color}` : "#78716c" });
      return lid;
    });

    let assigneeId: string | null = null;
    if (issue.assignee) {
      assigneeId = `gh:${issue.assignee.login}`;
      if (!people.some((p) => p.id === assigneeId)) {
        people.push({
          id: assigneeId,
          name: issue.assignee.login,
          initials: issue.assignee.login.slice(0, 2).toUpperCase(),
          role: "GitHub",
          color: IMPORT_LADDER[people.length % IMPORT_LADDER.length],
          avatarUrl: `${issue.assignee.avatar_url}${issue.assignee.avatar_url.includes("?") ? "&" : "?"}s=64`,
        });
      }
    }

    const body = issue.body ?? "";
    const tasks = Array.from(body.matchAll(TASK_RE)).map((m) => ({ text: m[2].trim(), done: m[1] !== " " }));
    const description = body
      .replace(TASK_RE, "")
      .replace(/\n{3,}/g, "\n\n")
      .trim()
      .slice(0, 1200);
    const columnId = issue.state === "closed" ? doneCol : openCol;
    const summary = issue.sub_issues_summary;

    const card: Card = {
      id,
      key: `#${issue.number}`,
      title: issue.title,
      description,
      columnId,
      labelIds,
      assigneeId,
      priority: priorityFromLabels(ghLabels.map((l) => l.name)),
      estimate: null,
      start: null,
      due: issue.milestone?.due_on?.slice(0, 10) ?? null,
      parentId: null,
      createdAt: issue.created_at?.slice(0, 10) ?? TODAY,
      closedAt: issue.closed_at?.slice(0, 10) ?? null,
      remoteProgress: summary && summary.total > 0 ? { done: summary.completed, total: summary.total } : undefined,
      activity: [{ id: `${id}a0`, text: `Imported from ${ref}`, at: shortDate(TODAY) }],
      source: { url: issue.html_url, ref },
    };
    cards = moveCard([...cards, card], id, columnId, null);
    added += 1;

    tasks.forEach((t, j) => {
      const m = t.text.match(ISSUE_REF_RE);
      if (m) {
        links.push({ parentRef: ref, childRef: `${repo}#${m[1]}` });
        return;
      }
      const cid = `${id}t${j}`;
      const col = t.done ? doneCol : columnId === doneCol ? openCol : columnId;
      const child: Card = {
        ...card,
        id: cid,
        key: `#${issue.number}.${j + 1}`,
        title: t.text,
        description: "",
        columnId: col,
        priority: 0,
        due: null,
        parentId: id,
        closedAt: t.done ? card.closedAt ?? TODAY : null,
        remoteProgress: undefined,
        activity: [{ id: `${cid}a0`, text: `From the task list on ${ref}`, at: shortDate(TODAY) }],
        source: undefined,
      };
      cards = moveCard([...cards, child], cid, col, null);
      added += 1;
    });
  }

  for (const { parentRef, childRef } of links) {
    const parent = cards.find((c) => c.source?.ref === parentRef);
    const child = cards.find((c) => c.source?.ref === childRef);
    if (parent && child && !child.parentId && child.id !== parent.id) {
      cards = cards.map((c) => (c.id === child.id ? { ...c, parentId: parent.id } : c));
    }
  }
  return { board: { ...b, labels, people, cards, seq }, added };
}

type Fetched = { repo: string; issues: GhIssue[] };

function GithubImportDialog({
  board,
  onImport,
  onClose,
}: {
  board: Board;
  onImport: (repo: string, issues: GhIssue[], column: string) => void;
  onClose: () => void;
}) {
  const reduce = useReducedMotion();
  const ref = useRef<HTMLDivElement>(null);
  const inputRef = useRef<HTMLInputElement>(null);
  const headingId = useId();
  useFocusTrap(ref, inputRef);
  useEscape(onClose);

  const [repoText, setRepoText] = useState("");
  const [token, setToken] = useState("");
  const [showToken, setShowToken] = useState(false);
  const [includeClosed, setIncludeClosed] = useState(false);
  const [col, setCol] = useState(0);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [fetched, setFetched] = useState<Fetched | null>(null);
  const [picked, setPicked] = useState<Set<number>>(() => new Set());
  const abort = useRef<AbortController | null>(null);
  useEffect(() => () => abort.current?.abort(), []);

  const onBoard = useMemo(() => new Set(board.cards.map((c) => c.source?.ref).filter(Boolean)), [board.cards]);

  const load = async () => {
    const repo = parseRepo(repoText);
    if (!repo) {
      setError("Use owner/repo, for example facebook/react, or paste the repo's URL.");
      return;
    }
    abort.current?.abort();
    const ctl = new AbortController();
    abort.current = ctl;
    setLoading(true);
    setError(null);
    setFetched(null);
    try {
      const res = await fetch(
        `https://api.github.com/repos/${repo}/issues?state=${includeClosed ? "all" : "open"}&per_page=50&sort=updated`,
        {
          signal: ctl.signal,
          headers: {
            Accept: "application/vnd.github+json",
            ...(token.trim() ? { Authorization: `Bearer ${token.trim()}` } : {}),
          },
        }
      );
      if (!res.ok) {
        if (res.status === 404)
          throw new Error(`No repo called ${repo} that this ${token ? "token" : "browser"} can see. Private repos need a token.`);
        if (res.status === 401) throw new Error("GitHub did not accept that token.");
        if ((res.status === 403 || res.status === 429) && res.headers.get("x-ratelimit-remaining") === "0") {
          const reset = Number(res.headers.get("x-ratelimit-reset")) * 1000;
          const when = reset ? new Date(reset).toLocaleTimeString([], { hour: "numeric", minute: "2-digit" }) : "later";
          throw new Error(
            `GitHub allows 60 signed-out requests an hour and they are spent. Add a token, or try again after ${when}.`
          );
        }
        throw new Error(`GitHub answered ${res.status}. Try again in a moment.`);
      }
      const issues = ((await res.json()) as GhIssue[]).filter((i) => !i.pull_request);
      setFetched({ repo, issues });
      setPicked(new Set(issues.filter((i) => !onBoard.has(`${repo}#${i.number}`)).map((i) => i.id)));
    } catch (e) {
      if ((e as Error).name === "AbortError") return;
      setError((e as Error).message || "Could not reach GitHub.");
    } finally {
      if (abort.current === ctl) setLoading(false);
    }
  };

  const fresh = fetched?.issues.filter((i) => !onBoard.has(`${fetched.repo}#${i.number}`)) ?? [];
  const chosen = fresh.filter((i) => picked.has(i.id));
  const allOn = fresh.length > 0 && chosen.length === fresh.length;

  return (
    <div
      className="pointer-events-auto absolute inset-0 z-40 flex items-start justify-center overflow-y-auto overscroll-contain p-4 pt-12 sm:pt-16"
      data-lenis-prevent
    >
      <motion.div
        ref={ref}
        role="dialog"
        aria-modal="true"
        aria-labelledby={headingId}
        initial={reduce ? { opacity: 0 } : { opacity: 0, scale: 0.96, y: 8 }}
        animate={{ opacity: 1, scale: 1, y: 0 }}
        exit={reduce ? { opacity: 0 } : { opacity: 0, scale: 0.98, transition: { duration: 0.14, ease: EASE_OUT } }}
        transition={{ duration: 0.24, ease: EASE_OUT }}
        className="relative flex max-h-[calc(100%-32px)] w-full max-w-lg flex-col rounded-2xl border border-stone-200 bg-white ring-1 ring-stone-900/5 shadow-[0_1px_2px_-1px_rgba(0,0,0,0.06),0_24px_48px_-16px_rgba(28,25,23,0.25)] dark:border-stone-800 dark:bg-stone-900 dark:ring-white/10 dark:shadow-none"
      >
        <div className="flex shrink-0 items-center gap-2 border-b border-stone-200 px-5 py-3 dark:border-stone-800">
          <GithubMark className="h-4 w-4 text-stone-900 dark:text-stone-100" />
          <h2 id={headingId} className="text-sm font-medium text-stone-900 dark:text-stone-100">
            Import issues from GitHub
          </h2>
          <span className="flex-1" />
          <button type="button" onClick={onClose} className={ICON_BTN} aria-label="Close">
            <X aria-hidden className="h-4 w-4" />
          </button>
        </div>

        <form
          className="flex shrink-0 flex-col gap-3 px-5 pt-5"
          onSubmit={(e) => {
            e.preventDefault();
            void load();
          }}
        >
          <div className="flex gap-2">
            <input
              ref={inputRef}
              value={repoText}
              onChange={(e) => setRepoText(e.target.value)}
              placeholder="owner/repo"
              aria-label="Repository"
              spellCheck={false}
              autoCapitalize="off"
              className={cn(INPUT, "h-9 min-w-0 flex-1 font-[family-name:var(--font-deck-mono)] text-xs")}
            />
            <button type="submit" disabled={loading || !repoText.trim()} className={PRIMARY}>
              {loading ? <LoaderCircle aria-hidden className="h-4 w-4 animate-spin motion-reduce:animate-none" /> : null}
              {loading ? "Fetching" : "Fetch issues"}
            </button>
          </div>
          <div className="flex flex-wrap items-center gap-x-4 gap-y-2 text-xs text-stone-600 dark:text-stone-400">
            <label className="inline-flex cursor-pointer items-center gap-2">
              <input
                type="checkbox"
                checked={includeClosed}
                onChange={(e) => setIncludeClosed(e.target.checked)}
                className="h-4 w-4 rounded accent-emerald-700"
              />
              Include closed (they land in Done)
            </label>
            <button
              type="button"
              onClick={() => setShowToken((v) => !v)}
              aria-expanded={showToken}
              className={cn("underline-offset-2 hover:underline", FOCUS)}
            >
              {showToken ? "Hide token" : "Private repo? Add a token"}
            </button>
          </div>
          {showToken && (
            <div className="flex flex-col gap-1">
              <input
                type="password"
                value={token}
                onChange={(e) => setToken(e.target.value)}
                placeholder="github_pat_..."
                aria-label="GitHub token"
                autoComplete="off"
                className={cn(INPUT, "h-8 font-[family-name:var(--font-deck-mono)] text-xs")}
              />
              <span className="text-[11px] leading-4 text-stone-500">
                A fine-grained token with read access to issues. It stays in this tab&apos;s memory and is sent only to
                api.github.com.
              </span>
            </div>
          )}
        </form>

        <div className="min-h-0 flex-1 overflow-y-auto overscroll-contain px-5 py-4" data-lenis-prevent aria-live="polite">
          {error && (
            <p
              role="alert"
              className="rounded-lg border border-stone-300 bg-stone-100 px-3 py-2 text-xs leading-5 text-stone-700 dark:border-stone-700 dark:bg-stone-950 dark:text-stone-300"
            >
              {error}
            </p>
          )}
          {fetched && fetched.issues.length === 0 && (
            <p className="py-6 text-center text-sm text-stone-500">
              No {includeClosed ? "" : "open "}issues in {fetched.repo}.
            </p>
          )}
          {fetched && fetched.issues.length > 0 && (
            <div className="flex flex-col gap-2">
              <div className="flex items-center gap-2">
                <span className={EYEBROW}>{fetched.repo}</span>
                <span className="text-xs tabular-nums text-stone-500">
                  {chosen.length} of {fresh.length} selected
                </span>
                <span className="flex-1" />
                {fresh.length > 0 && (
                  <button
                    type="button"
                    onClick={() => setPicked(allOn ? new Set() : new Set(fresh.map((i) => i.id)))}
                    className={cn("text-xs text-stone-600 underline-offset-2 hover:underline dark:text-stone-400", FOCUS)}
                  >
                    {allOn ? "Select none" : "Select all"}
                  </button>
                )}
              </div>
              <ul className="flex flex-col divide-y divide-stone-200 rounded-xl border border-stone-200 dark:divide-stone-800 dark:border-stone-800">
                {fetched.issues.map((i) => {
                  const already = onBoard.has(`${fetched.repo}#${i.number}`);
                  return (
                    <li key={i.id}>
                      <label
                        className={cn(
                          "flex items-start gap-3 px-3 py-2.5",
                          already ? "opacity-60" : "cursor-pointer hover:bg-stone-50 dark:hover:bg-stone-800/60"
                        )}
                      >
                        <input
                          type="checkbox"
                          disabled={already}
                          checked={already || picked.has(i.id)}
                          onChange={() =>
                            setPicked((s) => {
                              const next = new Set(s);
                              if (next.has(i.id)) next.delete(i.id);
                              else next.add(i.id);
                              return next;
                            })
                          }
                          className="mt-0.5 h-4 w-4 shrink-0 rounded accent-emerald-700"
                        />
                        <span className="min-w-0 flex-1">
                          <span className="block text-sm leading-5 text-stone-900 dark:text-stone-100">{i.title}</span>
                          <span className="mt-0.5 flex items-center gap-2 text-xs text-stone-500">
                            <span className="font-[family-name:var(--font-deck-mono)]">#{i.number}</span>
                            <span
                              className={cn(
                                "inline-flex items-center gap-1",
                                i.state === "open" ? "text-green-700 dark:text-green-400" : "text-stone-500"
                              )}
                            >
                              <span
                                aria-hidden
                                className={cn("h-1.5 w-1.5 rounded-full", i.state === "open" ? "bg-green-600" : "bg-stone-400")}
                              />
                              {i.state === "open" ? "Open" : "Closed"}
                            </span>
                            {already && <span>On the board</span>}
                          </span>
                        </span>
                      </label>
                    </li>
                  );
                })}
              </ul>
            </div>
          )}
          {!fetched && !error && (
            <p className="py-4 text-xs leading-5 text-stone-500">
              Labels come across in their GitHub colours, the milestone&apos;s due date becomes the card&apos;s, and each
              task-list item becomes a sub-issue card (or links the issue it names). Issues already on the board are skipped.
            </p>
          )}
        </div>

        <div className="flex shrink-0 flex-wrap items-center gap-2 border-t border-stone-200 px-5 py-3 dark:border-stone-800">
          <span className="text-xs text-stone-500">Open issues go to</span>
          <Select
            size="sm"
            label="Column for open issues"
            options={board.columns.map((c) => c.name)}
            value={Math.min(col, board.columns.length - 1)}
            onChange={setCol}
          />
          <span className="flex-1" />
          <button type="button" onClick={onClose} className={GHOST}>
            Cancel
          </button>
          <button
            type="button"
            disabled={chosen.length === 0}
            onClick={() => fetched && onImport(fetched.repo, chosen, board.columns[Math.min(col, board.columns.length - 1)].id)}
            className={PRIMARY}
          >
            Import {chosen.length > 0 ? chosen.length : ""} {chosen.length === 1 ? "card" : "cards"}
          </button>
        </div>
      </motion.div>
    </div>
  );
}

/* ------------------------------------------------------------------------ */
/* Progress and status tint                                                  */
/* ------------------------------------------------------------------------ */

/** A card's fill and border, tinted with its status column's colour in CSS. */
function cardVars(color: string): CSSProperties {
  return {
    "--card-bg": `color-mix(in oklab, ${color} 7%, #ffffff)`,
    "--card-line": `color-mix(in oklab, ${color} 34%, #ffffff)`,
    "--card-bg-dark": `color-mix(in oklab, ${color} 11%, #1c1917)`,
    "--card-line-dark": `color-mix(in oklab, ${color} 40%, #1c1917)`,
  } as CSSProperties;
}

interface CardProgress {
  value: number;
  label: string;
  items: Progress | null;
  complete: boolean;
  text: string;
}

/**
 * Every card gets a reading. Its sub-issues when it has any;
 * otherwise how far along the columns it has travelled, so a card with no
 * breakdown still shows where it stands.
 */
function cardProgress(card: Card, ctx: BoardCtx): CardProgress {
  const items = progressOf(card, ctx.kids);
  if (items) {
    return {
      value: items.done / items.total,
      label: `${items.done}/${items.total}`,
      items,
      complete: items.done === items.total,
      text: `${items.done} of ${items.total} sub-issues done`,
    };
  }
  const cols = ctx.board.columns;
  const i = Math.max(
    0,
    cols.findIndex((c) => c.id === card.columnId)
  );
  const value = card.columnId === DONE_ID ? 1 : cols.length > 1 ? i / (cols.length - 1) : 0;
  const pct = Math.round(value * 100);
  return { value, label: `${pct}%`, items: null, complete: value === 1, text: `${pct} percent of the way through the columns` };
}

function ProgressMeter({ p, className }: { p: CardProgress; className?: string }) {
  const segs = p.items && p.items.total <= 12 ? p.items.total : 0;
  const fill = p.complete ? "bg-green-600" : "bg-emerald-700 dark:bg-emerald-500";
  return (
    <div
      className={cn("flex items-center gap-2", className)}
      role="progressbar"
      aria-valuemin={0}
      aria-valuemax={100}
      aria-valuenow={Math.round(p.value * 100)}
      aria-label={p.text}
    >
      {segs ? (
        <div className="flex h-1.5 min-w-0 flex-1 gap-0.5" aria-hidden>
          {Array.from({ length: segs }, (_, i) => (
            <span key={i} className={cn("flex-1 rounded-full", i < p.items!.done ? fill : "bg-stone-200 dark:bg-stone-700")} />
          ))}
        </div>
      ) : (
        <div className="h-1.5 min-w-0 flex-1 overflow-hidden rounded-full bg-stone-200 dark:bg-stone-700" aria-hidden>
          <div
            className={cn("h-full origin-left rounded-full transition-transform duration-300", fill)}
            style={{ transform: `scaleX(${p.value})` }}
          />
        </div>
      )}
      <span
        className={cn(
          "shrink-0 text-[11px] leading-4 tabular-nums",
          p.complete ? "text-green-700 dark:text-green-400" : "text-stone-500"
        )}
      >
        {p.label}
      </span>
    </div>
  );
}

/* ------------------------------------------------------------------------ */
/* Filter bar                                                                */
/* ------------------------------------------------------------------------ */

interface QItem {
  kind: "field" | "value";
  insert: string;
  label: string;
  hint?: string;
  adorn?: ReactNode;
  disabled?: boolean;
}

const Dot = ({ color }: { color: string }) => (
  <span
    aria-hidden
    className="h-2.5 w-2.5 shrink-0 rounded-full ring-1 ring-inset ring-black/15 dark:ring-white/20"
    style={{ background: color }}
  />
);

function suggestionsFor(c: QContext | null, bc: BoardCtx, hasRepos: boolean): QItem[] {
  if (!c) return [];
  const pre = c.prefix.toLowerCase();
  if (c.kind === "field") {
    return Q_FIELDS.filter(
      (f) => (f.key !== "repo" || hasRepos) && (!pre || f.key.startsWith(pre) || f.label.toLowerCase().startsWith(pre))
    ).map((f) => {
      const Icon = f.icon;
      return {
        kind: "field" as const,
        insert: `${c.neg ? "-" : ""}${f.key}:`,
        label: f.label,
        hint: f.hint,
        adorn: <Icon aria-hidden className="h-4 w-4 shrink-0 text-stone-500" />,
      };
    });
  }

  const count = (pred: (card: Card) => boolean) => String(bc.board.cards.filter(pred).length);
  let values: { value: string; label: string; hint?: string; adorn?: ReactNode; disabled?: boolean }[] = [];
  switch (c.field) {
    case "is":
      values = [
        { value: "open", label: "open", hint: "not in Done" },
        { value: "done", label: "done", hint: "in Done" },
        { value: "overdue", label: "overdue", hint: "past due" },
        { value: "due-soon", label: "due-soon", hint: "within 2 days" },
        { value: "assigned", label: "assigned" },
        { value: "unassigned", label: "unassigned" },
        { value: "parent", label: "parent", hint: "has sub-issues" },
        { value: "sub-issue", label: "sub-issue", hint: "has a parent" },
        ...(hasRepos ? [{ value: "imported", label: "imported", hint: "from GitHub" }] : []),
      ];
      break;
    case "assignee":
      values = [
        ...bc.board.people.map((p) => ({
          value: handleOf(p),
          label: p.name,
          hint: count((card) => card.assigneeId === p.id),
          adorn: <Initials person={p} size="xs" />,
        })),
        { value: "none", label: "No assignee", hint: count((card) => !card.assigneeId) },
      ];
      break;
    case "label":
      values = bc.board.labels.map((l) => ({
        value: l.name,
        label: l.name,
        hint: count((card) => card.labelIds.includes(l.id)),
        adorn: <Dot color={l.color} />,
      }));
      break;
    case "status":
      values = bc.board.columns.map((col) => ({
        value: col.name,
        label: col.name,
        hint: count((card) => card.columnId === col.id),
        adorn: <Dot color={col.color} />,
      }));
      break;
    case "priority":
      values = ([4, 3, 2, 1, 0] as Priority[]).map((p) => ({
        value: PRIORITY_KEYS[p],
        label: PRIORITIES[p],
        hint: count((card) => card.priority === p),
        adorn: <PriorityGlyph priority={p} />,
      }));
      break;
    case "due":
      values = [
        { value: "overdue", label: "overdue" },
        { value: "today", label: "today" },
        { value: "this-week", label: "this-week", hint: "next 7 days" },
        { value: "next-week", label: "next-week" },
        { value: "none", label: "none", hint: "no due date" },
      ];
      break;
    case "parent":
      values = [
        ...bc.board.cards
          .filter((card) => (bc.kids.get(card.id)?.length ?? 0) > 0)
          .map((card) => ({ value: card.key, label: `${card.key} ${card.title}`, hint: String(bc.kids.get(card.id)!.length) })),
        { value: "none", label: "No parent" },
      ];
      break;
    case "title":
      values = [{ value: "", label: "Type words from the title", disabled: true }];
      break;
    case "repo":
      values = Array.from(new Set(bc.board.cards.map((card) => card.source?.ref.split("#")[0]).filter(Boolean) as string[])).map(
        (r) => ({ value: r, label: r })
      );
      break;
  }
  return values
    .filter((v) => v.disabled || !pre || v.value.toLowerCase().includes(pre) || v.label.toLowerCase().includes(pre))
    .map((v) => ({
      kind: "value" as const,
      insert: quoteValue(v.value),
      label: v.label,
      hint: v.hint,
      adorn: v.adorn,
      disabled: v.disabled,
    }));
}

/** The query drawn behind a transparent input, so qualifiers read as tokens. */
function highlightQuery(q: string, tokens: QToken[]): ReactNode[] {
  const out: ReactNode[] = [];
  let pos = 0;
  tokens.forEach((t, i) => {
    if (t.start > pos) out.push(q.slice(pos, t.start));
    if (t.field) {
      out.push(
        <span key={`k${i}`} className={t.neg ? "text-red-700 dark:text-red-400" : "text-stone-600 dark:text-stone-400"}>
          {q.slice(t.start, t.keyEnd)}
        </span>
      );
      if (t.end > t.keyEnd) {
        out.push(
          <span
            key={`v${i}`}
            className="rounded-sm bg-emerald-500/15 text-emerald-800 dark:bg-emerald-400/15 dark:text-emerald-300"
          >
            {q.slice(t.keyEnd, t.end)}
          </span>
        );
      }
    } else {
      out.push(<span key={`t${i}`}>{q.slice(t.start, t.end)}</span>);
    }
    pos = t.end;
  });
  if (pos < q.length) out.push(q.slice(pos));
  return out;
}

function FilterBar({
  value,
  onChange,
  bc,
  hasRepos,
  count,
  total,
}: {
  value: string;
  onChange: (v: string) => void;
  bc: BoardCtx;
  hasRepos: boolean;
  count: number;
  total: number;
}) {
  const reduce = useReducedMotion();
  const inputRef = useRef<HTMLInputElement>(null);
  const mirrorRef = useRef<HTMLDivElement>(null);
  const measureRef = useRef<HTMLSpanElement>(null);
  const wrapRef = useRef<HTMLDivElement>(null);
  const listId = useId();
  const [caret, setCaret] = useState(0);
  const [open, setOpen] = useState(false);
  const [active, setActive] = useState(0);
  const listRef = useRef<HTMLUListElement>(null);

  const tokens = useMemo(() => tokenize(value), [value]);
  const at = useMemo(() => contextAt(value, caret), [value, caret]);
  const items = useMemo(() => suggestionsFor(at, bc, hasRepos), [at, bc, hasRepos]);
  const show = open && items.length > 0;
  const act = Math.min(active, Math.max(0, items.length - 1));

  // "/" focuses the filter from anywhere on the board, as it does on GitHub.
  useEffect(() => {
    const onKey = (e: KeyboardEvent) => {
      const el = document.activeElement;
      const typing =
        el instanceof HTMLInputElement || el instanceof HTMLTextAreaElement || (el as HTMLElement | null)?.isContentEditable;
      if (e.key === "/" && !typing && !e.metaKey && !e.ctrlKey) {
        e.preventDefault();
        inputRef.current?.focus();
        setOpen(true);
      }
    };
    window.addEventListener("keydown", onKey);
    return () => window.removeEventListener("keydown", onKey);
  }, []);

  // Hang the list under the word being typed, the way GitHub does. Written
  // straight to the element: it is layout, not state.
  useLayoutEffect(() => {
    if (!show || !listRef.current) return;
    const w = wrapRef.current?.offsetWidth ?? 0;
    const x = 36 + (measureRef.current?.offsetWidth ?? 0) - (inputRef.current?.scrollLeft ?? 0);
    listRef.current.style.left = `${Math.max(0, Math.min(x - 8, w - 288))}px`;
  }, [show, value, at?.from]);

  const sync = () => {
    const el = inputRef.current;
    if (!el) return;
    setCaret(el.selectionStart ?? el.value.length);
    if (mirrorRef.current) mirrorRef.current.scrollLeft = el.scrollLeft;
  };

  const pick = (item: QItem) => {
    if (!at || item.disabled) return;
    const after = value.slice(at.to);
    const insert = item.insert + (item.kind === "value" && !/^[\s,]/.test(after) ? " " : "");
    const next = value.slice(0, at.from) + insert + after;
    const pos = at.from + insert.length;
    onChange(next);
    setActive(0);
    requestAnimationFrame(() => {
      const el = inputRef.current;
      if (!el) return;
      el.focus();
      el.setSelectionRange(pos, pos);
      setCaret(pos);
      if (mirrorRef.current) mirrorRef.current.scrollLeft = el.scrollLeft;
    });
  };

  const step = (dir: 1 | -1) => {
    if (!items.length) return;
    let i = act;
    for (let n = 0; n < items.length; n++) {
      i = (i + dir + items.length) % items.length;
      if (!items[i].disabled) break;
    }
    setActive(i);
    document.getElementById(`${listId}-${i}`)?.scrollIntoView({ block: "nearest" });
  };

  return (
    <div ref={wrapRef} className="relative min-w-0 flex-1">
      <div className="relative flex h-9 items-center rounded-md border border-stone-300 bg-white transition-[border-color,box-shadow] duration-150 focus-within:border-emerald-600 focus-within:ring-2 focus-within:ring-emerald-600/25 dark:border-stone-700 dark:bg-stone-950 dark:focus-within:border-emerald-400 dark:focus-within:ring-emerald-400/25">
        <Search aria-hidden className="pointer-events-none absolute left-3 h-4 w-4 text-stone-500" />
        <div
          ref={mirrorRef}
          aria-hidden
          className="pointer-events-none absolute inset-y-0 left-9 right-28 overflow-hidden whitespace-pre text-sm leading-[34px] text-stone-900 dark:text-stone-100"
        >
          {highlightQuery(value, tokens)}
        </div>
        <span ref={measureRef} aria-hidden className="invisible absolute left-0 top-0 whitespace-pre text-sm">
          {value.slice(0, at?.from ?? caret)}
        </span>
        <input
          ref={inputRef}
          role="combobox"
          aria-label="Filter cards"
          aria-expanded={show}
          aria-controls={listId}
          aria-autocomplete="list"
          aria-activedescendant={show ? `${listId}-${act}` : undefined}
          value={value}
          spellCheck={false}
          autoComplete="off"
          placeholder="Filter by keyword or by field"
          onChange={(e) => {
            onChange(e.target.value);
            setOpen(true);
            setActive(0);
            requestAnimationFrame(sync);
          }}
          onFocus={() => {
            setOpen(true);
            sync();
          }}
          onBlur={() => setOpen(false)}
          onClick={() => {
            setOpen(true);
            sync();
          }}
          onKeyUp={(e) => {
            if (["ArrowLeft", "ArrowRight", "Home", "End"].includes(e.key)) {
              setActive(0);
              sync();
            }
          }}
          onScroll={sync}
          onKeyDown={(e) => {
            if (e.key === "ArrowDown") {
              e.preventDefault();
              if (!show) setOpen(true);
              else step(1);
            } else if (e.key === "ArrowUp" && show) {
              e.preventDefault();
              step(-1);
            } else if ((e.key === "Enter" || e.key === "Tab") && show && !items[act]?.disabled) {
              e.preventDefault();
              pick(items[act]);
            } else if (e.key === "Escape") {
              if (show) {
                e.stopPropagation();
                setOpen(false);
              } else inputRef.current?.blur();
            }
          }}
          className="h-full min-w-0 flex-1 bg-transparent pl-9 pr-28 text-sm text-transparent caret-stone-900 outline-none placeholder:text-stone-400 selection:bg-emerald-600/25 dark:caret-stone-100 dark:placeholder:text-stone-600"
        />
        <div className="absolute right-1.5 flex items-center gap-1">
          {value.trim() && (
            <span className="rounded-full bg-stone-100 px-2 text-[11px] leading-5 tabular-nums text-stone-600 dark:bg-stone-800 dark:text-stone-400">
              {count} of {total}
            </span>
          )}
          {value && (
            <button
              type="button"
              aria-label="Clear filter"
              onMouseDown={(e) => e.preventDefault()}
              onClick={() => {
                onChange("");
                setCaret(0);
                inputRef.current?.focus();
              }}
              className={cn(ICON_BTN, "h-6 w-6")}
            >
              <X aria-hidden className="h-3.5 w-3.5" />
            </button>
          )}
        </div>
      </div>

      <AnimatePresence>
        {show && (
          <motion.ul
            ref={listRef}
            id={listId}
            role="listbox"
            aria-label={at?.kind === "value" ? `${Q_FIELDS.find((f) => f.key === at.field)?.label} values` : "Filter fields"}
            initial={reduce ? { opacity: 0 } : { opacity: 0, y: -4, scale: 0.98 }}
            animate={{ opacity: 1, y: 0, scale: 1 }}
            exit={{ opacity: 0, transition: { duration: 0.1 } }}
            transition={{ duration: 0.15, ease: EASE_OUT }}
            style={{ transformOrigin: "top left" }}
            onMouseDown={(e) => e.preventDefault()}
            data-lenis-prevent
            className={cn(FLOATING, "absolute top-full z-40 mt-1.5 max-h-72 w-72 overflow-y-auto overscroll-contain p-1")}
          >
            {at?.kind === "value" && (
              <li role="presentation" className={cn(EYEBROW, "px-2 pb-1 pt-1.5")}>
                {Q_FIELDS.find((f) => f.key === at.field)?.label}
              </li>
            )}
            {items.map((it, i) => (
              <li
                key={`${it.kind}-${it.insert}-${i}`}
                id={`${listId}-${i}`}
                role="option"
                aria-selected={i === act}
                aria-disabled={it.disabled || undefined}
                onMouseEnter={() => !it.disabled && setActive(i)}
                onClick={() => pick(it)}
                className={cn(
                  "flex h-8 items-center gap-2 rounded-md px-2 text-sm",
                  it.disabled
                    ? "cursor-default text-stone-500"
                    : i === act
                    ? "cursor-pointer bg-stone-100 text-stone-900 dark:bg-stone-700 dark:text-stone-100"
                    : "cursor-pointer text-stone-700 dark:text-stone-200"
                )}
              >
                {it.adorn}
                <span className="min-w-0 flex-1 truncate">{it.label}</span>
                {it.hint && <span className="shrink-0 text-xs tabular-nums text-stone-500">{it.hint}</span>}
              </li>
            ))}
          </motion.ul>
        )}
      </AnimatePresence>
    </div>
  );
}

